insert into public.works (museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide)
select museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide
from jsonb_populate_recordset(null::public.works, $seed$[{"museum_id":"henan","language":"en","id":"henan-01","position":0,"title":"Bone Flute from Jiahu","category":"Musical Instruments","subtitle":"贾湖骨笛","artist":null,"facts":[{"label":"Period","value":"Neolithic, Peiligang culture (c. 7000–5700 BCE)"},{"label":"Type","value":"Bone musical instrument (flute)"},{"label":"Material","value":"Red-crowned crane ulna"}],"object_url":null,"image":{"src":"/images/paintings/henan-01.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Early_Peiligang_Culture_Bone_Flute,_Wuyang.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"Look closely at the small holes running along this flute. It was carved from the wing bone of a red-crowned crane, a bird whose bones are hard and hollow, which made them difficult to drill. Seven finger holes sit in a neat line along one side. Covering and opening them changes the pitch, so a player could move between notes using only the hands. The flute is about 23 centimetres long, small enough to rest in an adult's palm. It comes from Jiahu, a settlement in Wuyang, Henan Province, occupied during the early Neolithic Peiligang culture, roughly between 7000 and 5700 BC. It is among the oldest instruments of its kind, and it reminds us that music was being made in China millennia before the Shang dynasty. Look first, then imagine the sound it once made across a village.","expansion":"Its sound is the subject of serious study. In 1999, a team of Chinese and American researchers reported tests on the best-preserved Jiahu flute, which they had played and analysed. They found that its seven holes could correspond to a scale remarkably close to the Western do-re-mi eight-note scale. That claim is striking, but it rests largely on one instrument and on modern interpretation of ancient sound, so specialists treat it as provisional. The flute's context is also debated. A Henan Museum online exhibition links this example to a tomb at Jiahu and suggests it was the one most cherished by the person buried there. Other accounts of the excavations do not mention a tomb, so that connection needs checking.","long":"Start with the material. This flute was made from the wing bone of a red-crowned crane. Crane bone is hard but hollow, which is a challenge for any toolmaker. It holds a shape well, yet a drill can easily split it. Surviving examples show small marks carved above and between the holes before drilling began, a sign that the spacing was worked out in advance rather than guessed.\n\nSeven holes run in a straight line along one side. Covering and uncovering them with the fingers lets the player shift between pitches. Trial playing confirmed that the instrument is blown vertically, the same basic principle as many later flutes. Some accounts describe smaller holes beside the main seven that may have been used for tuning, but this detail comes from a single source, so treat it with care.\n\nThis example was found at Jiahu, a settlement in Wuyang County, Henan. The site was occupied during the Peiligang culture, roughly between 7000 and 5700 BC. Excavators have recovered more than thirty bone flutes there, most in fragments. According to the Henan Museum's online presentation, this flute was unearthed in 1987. Its three pieces show that it was broken and carefully mended in antiquity, so someone thought it worth keeping.\n\nHere the story becomes debated. In 1999, researchers reported that the best-preserved Jiahu flute could be played and tonally analysed, and that its seven holes might correspond to a scale close to the Western do-re-mi eight-note scale. That is a remarkable result, but it depends heavily on one instrument and on modern interpretation of ancient sound.\n\nWe do not know what these flutes were for. Some researchers suspect ritual or ceremonial use, but the site does not reveal what tunes were played or who played them. Chinese myths recorded thousands of years later link flute playing with cranes, but whether that association existed at Jiahu is not known.\n\nSo why does this object matter today? It is one of the earliest known instruments that can still produce controlled, multi-note sounds. It shows that early farming communities in the Central Plains were already working with precise acoustics, shaping a hard material into an instrument that could be tuned by hand and played by ear. Look at it first as a made object, a piece of skilled craft. Then listen to it in your imagination."}},{"museum_id":"henan","language":"en","id":"henan-02","position":1,"title":"Owl-shaped Zun of Lady Fu Hao","category":"Bronzes","subtitle":"妇好鸮尊","artist":null,"facts":[{"label":"Period","value":"Late Shang dynasty (c. 13th–11th century BCE)"},{"label":"Type","value":"Bronze ritual wine vessel (zun, owl-shaped)"},{"label":"Material","value":"Bronze"},{"label":"Size","value":"Height 46.3 cm; weight 16 kg"}],"object_url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512159573394606792","image":{"src":"/images/paintings/henan-02.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Bronze_owl-shaped_Zun_with_inscriptions_of_Fu_Hao,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Look first at the head. Two small ears rise from a high crown, the eyes are round, the beak is broad, and the wings are folded tight against the body. This is an owl, cast in bronze in the late Shang dynasty, around 1200 BCE, and it is a ritual wine vessel. Notice how it stands. Its strong legs and broad, drooping tail meet the ground at three points, so the tail does structural work rather than merely decorating the piece. Now bend toward the rim. Just below the mouth, on the inner wall, two characters are cast: 妇好, Fu Hao. That inscription links the vessel to Fu Hao, a consort of King Wu Ding, whose tomb was excavated at Yinxu near Anyang in 1976. Roughly 3,200 years later, the owl still stands on its three points.","expansion":"The surface is as striking as the silhouette. Nearly every part is covered in thunder pattern, leiwen, 雷纹, a fine ground that gives the bronze a dense, textured look. Over it, cicadas appear on the beak and chest, a double-headed kui dragon, 夔, sits on each side of the neck, and coiled snakes curl near the wings. Taotie masks, the mysterious beast faces typical of Shang bronzes, appear among them. The result is busy, yet the owl’s outline stays clear. Curators at the museum describe the bird as sacred and linked to bravery and victory. One scholar has argued that it represents a war god, but that is an interpretation, not a settled fact. The pair also matters: the other owl is in the National Museum of China in Beijing, and the two were shown together in Henan for the first time.","long":"Start with the silhouette. This is an owl, rendered in bronze more than three thousand years ago, and it stands on three points: two thick legs and a broad, drooping tail that meets the ground as firmly as the feet. Look at the head. A high crown rises above small ears, the eyes are round, and the beak is wide. The wings are folded tightly against the sides, so the bird seems both still and alert. That tension between stillness and watchfulness is what makes the piece feel alive.\n\nIt is a zun, a ritual wine vessel. Shang bronzes of this kind were used in ritual settings, and the bird’s body is the container itself, with an opening at the top. The animal form and the working vessel are one object.\n\nThe surface is dense. Almost all of it is covered in thunder pattern, leiwen, 雷纹, a fine ground that makes the bronze look textured. Over that ground, cicadas appear on the beak and chest, double-headed kui dragons, 夔, sit on the neck, and taotie masks and coiled snakes appear elsewhere on the body. The museum describes the overall style as dignified and fierce, yet the owl’s outline stays clear.\n\nThen look just below the mouth, on the inside of the vessel. Two characters are cast there: 妇好, Fu Hao. The inscription identifies the owner. Fu Hao was a consort of King Wu Ding, and her tomb was excavated in 1976 at Yinxu, the late Shang capital near modern Anyang. The tomb was undisturbed when found and held hundreds of bronzes. Oracle bone inscriptions also name her as a military leader.\n\nWhy an owl? Curators at the museum describe the bird as sacred and link it to bravery and victory. One scholar has gone further and argued that the owl was a war-god symbol, but that reading is an interpretation rather than a settled fact. Owls also carried different reputations in later Chinese history, so their meaning should not be assumed to stay fixed.\n\nFinally, this is one of a pair. The other owl is in the National Museum of China in Beijing, and the two were shown together in Henan for the first time in a recent exhibition. Whether you stand before one owl or two, the question is the same: how did Shang workers make an animal look so watchful?"}},{"museum_id":"henan","language":"en","id":"henan-03","position":2,"title":"Lianhe Fanghu (Square Hu with Lotus and Crane)","category":"Bronzes","subtitle":"莲鹤方壶","artist":null,"facts":[{"label":"Period","value":"Spring and Autumn period (770–476 BCE)"},{"label":"Type","value":"Bronze vessel (square hu)"},{"label":"Material","value":"Bronze"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zpjc/qtq/articlea5e2192480c947a0846136edc2adeb21.html","image":{"src":"/images/paintings/henan-03.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Rectangular_Pots_with_Lotus_Petal_Cover_and_Crane_Decoration_01.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Begin at the top. On the lid, a crane stands with its wings spread, as if about to take flight, and two tiers of lotus petals open around it. The petals are pierced with many tiny holes, so the lid is worked almost like lace. Now follow the eye down the body. The vessel is square in section, with a rectangular mouth, a long neck, and a belly that swells and then tapers toward the base. Dragons climb its corners, heads turned back over their shoulders, and creatures crouch beneath the foot to bear its weight. This is a hu, a vessel for holding wine or another liquid. It was cast in bronze around the sixth century BCE, in the late Spring and Autumn period, when Zhou royal authority was weakening. Notice how every line in the design rises toward the crane.","expansion":"The story of this vessel begins underground. In 1923, digging at Lijialou, near Xinzheng in Henan, uncovered bronzes from a large tomb traditionally linked to the rulers of Zheng, a small state of the period. The occupant has not been securely identified; scholars have proposed a few Zheng dukes, and the question remains open. Burial matters here. In a tomb, bronzes of this scale signaled the rank of the person buried there, but the record does not fully reveal how such a vessel was used while the living held it. The lotus and crane are commonly read as symbols of purity and longevity. That reading is plausible, yet it is an interpretation, not a documented intention. The Henan Museum holds one of a pair. The twin was separated long ago, and today the other sits in Beijing, at the Palace Museum.","long":"Start with the crane. Standing on the lid of this bronze, it has its wings spread as if about to lift off, and it rises from two tiers of lotus petals that open outward like a flower in bloom. The petals are pierced with many small holes, so the lid is a delicate openwork frame rather than a solid cap. Now look at the body. It is square in section, with a rectangular mouth, a long neck, and a belly that swells and tapers toward the foot. Dragons climb its corners with their heads turned back, and mythical creatures crouch beneath the base to support its weight. The whole thing is cast in bronze, and it is heavy. Some sources give its weight as about 64 kilograms, but published measurements vary, so treat the exact figures as provisional.\n\nThis is a hu, a vessel for holding wine or another liquid. Its shape suggests it was made for pouring, and its scale suggests it was meant to impress. It was cast during the late Spring and Autumn period, roughly the sixth century BCE, when the Zhou royal house still held nominal authority but regional states such as Zheng were asserting their own power. Bronzes of this size and finish were a statement of rank.\n\nThe vessel was found in 1923, in a field at Lijialou near Xinzheng, Henan, in what was traditionally identified as a tomb of the Zheng rulers. Finding it in a tomb tells us where it ended up, but the record does not fully reveal how it was used while the living held it. The occupant of that tomb has not been securely identified, and scholars have proposed a few Zheng dukes. The pair was later divided. One vessel is here in Zhengzhou, and the other is in Beijing's Palace Museum.\n\nThe scholar Guo Moruo gave it the name Lianhe fanghu, the lotus-and-crane square hu. The name captures the two motifs that define the design. The lotus and crane are often read as symbols of purity and longevity, a reading that is plausible but reflects later interpretation rather than a documented intention. What we can say with more confidence is that the lid, the body, and the dragons were designed as one composition, with the crane as its focal point. Pay attention to it, and you will see how nearly every line leads upward toward it."}},{"museum_id":"henan","language":"en","id":"henan-04","position":3,"title":"Wu Zetian Gold Slip","category":"Jade, Gold & Weapons","subtitle":"武则天金简","artist":null,"facts":[{"label":"Period","value":"Tang dynasty, Wu Zhou period (700 CE)"},{"label":"Type","value":"Gold ritual slip with inscription"},{"label":"Material","value":"Gold alloy (about 90% gold, 10% silver, per museum testing)"}],"object_url":null,"image":{"src":"/images/paintings/henan-04.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Wu_Zetian_Gold_Strip,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Start with the material. This narrow strip of gold, about thirty-six centimetres long, is covered in more than sixty characters, and it was never meant for a display case. It is a petition. Around the year 700, Wu Zetian, the only woman to rule China as emperor, sent a Daoist envoy to Mount Song in Henan with this slip. Its message asks the celestial authorities to pardon the empress's wrongdoings. Look at the surface and you will see the characters were not stamped but cut into the metal by hand, one stroke at a time. Earlier slips of this kind were made of jade, silver or bronze, so this is the first known gold example. Read the lines slowly, and you are reading a personal request, issued in the empress's own name, meant for the gods.","expansion":"Now look at how it was made. The gold was hammered into a sheet only about a millimetre thick, and the characters were incised as outlines, each stroke drawn with a pair of parallel lines, a technique called double-line writing. The surface was then burnished smooth. The metal is not pure gold. A 2008 test by the Henan Museum found roughly ninety percent gold and ten percent silver, a proportion reported as typical of Tang gold, though another published figure gives higher purity, so the exact composition is still open. The strip survived by chance. In 1982, a young farmer on Junji Peak, a summit of Mount Song, took it for pastry wrapping. Only after he wiped away the dirt did he see the writing. A dealer offered him 100,000 yuan, and he handed the slip to the state instead.","long":"Picture a sheet of gold, long and narrow, that you could hold in one hand. It looks like an ornament, but it was never meant for a display case. This is a petition, and its author was an empress.\n\nWu Zetian is the only woman in Chinese history to rule as emperor. She founded her own Zhou dynasty, which interrupted the Tang for about fifteen years. In the year 700, the inscription tells us, she sent a Daoist envoy named Hu Chao to Mount Song, one of China's five sacred mountains. He was to leave the slip there, asking the Three Officials and the Nine Bureaus, the celestial authorities in Daoist belief, to pardon her wrongdoings. The text is dated the seventh day of the seventh month.\n\nThe wording is short but deliberate. Five of its characters were ones Wu Zetian had created herself, including 曌, the character she devised for her own name. That suggests a personal hand in the wording, although the record names Hu Chao as the envoy who submitted it. The slip was first nicknamed after its supposed purpose, the removal of the empress's sins, and that label still shapes how people read it.\n\nHere the debate begins. The word for sin could mean a moral failing, but it could also refer to suffering, such as illness. Some writers link the slip to an illness the empress is recorded as having around that time, and to pills Hu Chao had made for her. That reading is an inference, not something the inscription says outright. Later researchers tend to read the slip as a prayer for blessing and protection.\n\nWhatever the precise motive, the object shows a ruler at the height of her power turning to the mountains and the gods, and choosing gold to do it. Whether you read it as a confession, a plea, or a prayer for health, the slip carries a voice that official histories rarely give us: a sovereign asking, in her own careful language, for forgiveness."}},{"museum_id":"henan","language":"en","id":"henan-05","position":4,"title":"Bronze Jin Stand with Cloud Pattern","category":"Bronzes","subtitle":"云纹铜禁","artist":null,"facts":[{"label":"Period","value":"Late Spring and Autumn period (cast no later than 552 BCE)"},{"label":"Type","value":"Bronze stand for wine vessels (jin)"},{"label":"Material","value":"Bronze"},{"label":"Size","value":"Height 28.8 cm; length 103 cm; width 46 cm; weight 95.5 kg"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/mzyp/article9ff964490b3b4f02be4f5e622a87614f.html","image":{"src":"/images/paintings/henan-05.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Spring_%26_Autumn_Bronze_Jin_-_10336384816.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"Start with the top, because that is where your eye goes first. What looks like a solid tray turns out to be a lattice of cast cloud scrolls, pierced so you can see through to the hollow frame below. This is a jin, a bronze stand built to hold a wine vessel. It dates to the late Spring and Autumn period, around the sixth century BC, and was made for the Chu state, whose tombs at Xichuan in Henan have yielded this piece. Twelve dragon-shaped beasts cling to the sides of the frame, their open jaws and extended tongues turned toward the center. Twelve more beasts sit beneath and carry the load. The whole piece is about 29 centimeters tall, yet it weighs roughly 95 kilograms. Few bronzes manage to be this heavy and this delicate at once.","expansion":"The stand also raises a question about how it was made. The museum's record calls it one of the earliest Chinese bronzes cast by the lost-wax method. In that process, the form is modeled in wax, coated in clay, and the wax is melted out, leaving a cavity that molten bronze fills. Many scholars place the arrival of lost-wax casting in China much later, and often connect it with India. If this stand was truly lost-wax cast, the technique would be far older than the early Tang texts usually cited for it. Other researchers doubt that Bronze Age workshops used the method at all. They argue the stand was assembled from separately molded pieces joined by welding. The debate remains open. Either way, its makers controlled molten metal across a large and intricately pierced form, which is a remarkable achievement in itself.","long":"Lift your eyes to the top of this bronze. What looks like a solid tray is really a lattice of cloud scrolls, pierced so you can look straight through them to the hollow frame beneath. The whole piece is about 29 centimeters tall and weighs roughly 95 kilograms, and nearly all of that mass rests on twelve beasts crouched under the frame.\n\nIt is a jin, a stand made to hold a wine vessel. The word is usually read as \"prohibition,\" and a long-standing explanation links the name to the Zhou view that excessive drinking had doomed the Xia and Shang dynasties. That is a traditional explanation, not something the object itself proves. What the object does show is how carefully its makers handled wine. Twelve dragon-shaped beasts cling to its sides, their open mouths turned toward the center and their tongues extended. Some other accounts describe the lower beasts as tiger-like, but the museum's record calls them dragons.\n\nThe stand comes from the Chu state in the late Spring and Autumn period. It was found at Xiasi, in Xichuan county, Nanyang, Henan, and the official record dates its casting to no later than 552 BC. Local bronzes first came to light in 1977, when a drought lowered the water in the Danjiangkou reservoir. The tomb owner is commonly identified as Zi Geng, also called Prince Wuzi, a chief minister of Chu. That identification rests mainly on inscriptions on a set of ding cauldrons from the same tomb, not on the stand itself.\n\nThe bigger question is how it was cast. The museum describes it as one of the earliest Chinese bronzes made by lost-wax casting, a method in which a wax model is coated in clay and melted away to leave a cavity for molten bronze. If that is right, the technique would be far older than the Tang-dynasty texts that are usually cited for it. Many scholars instead place the arrival of lost-wax casting in China much later and connect it with India. Others doubt that the Bronze Age used the method at all, and argue that the stand was assembled from separately molded pieces joined by welding. The debate remains open.\n\nWhichever way it was made, the stand shows a workshop able to control molten metal across a large and intricately pierced form."}},{"museum_id":"henan","language":"en","id":"henan-06","position":5,"title":"Duling Square Ding","category":"Bronzes","subtitle":"杜岭方鼎","artist":null,"facts":[{"label":"Period","value":"Early Shang dynasty (c. 16th–15th century BCE)"},{"label":"Type","value":"Bronze ritual vessel (square ding)"},{"label":"Material","value":"Bronze"},{"label":"Size","value":"Height 87 cm; weight about 64.25 kg"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zyzb/articlecc3a53c2a97149d4bf62fb583ef0dc9d.html","image":{"src":"/images/paintings/henan-06.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20250527_Nipple-nailed_square_ding_with_beast_face_patterns_in_the_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Yumeto"},"guide":{"short":"Walk slowly around this bronze and begin with its corners. The body is square, with straight walls and a flat rim, and it stands on four hollow legs. It is a ding, a ritual vessel of the Shang dynasty used to hold food at ceremonies. This example is about 87 centimeters tall and weighs roughly 64 kilograms, so even empty it is a heavy object. It dates to the early Shang period, around 3,400 years ago. Look at the upper belly, where a fierce face called a taotie stares out of the bronze. Along the sides and lower body, small raised knobs, known as nipple bosses, break up the surface. Their purpose is debated, but their orderly placement shows how carefully the surface was planned. You are looking at the smaller of a pair of dings found together in Zhengzhou in 1974.","expansion":"Here is a question this vessel leaves open: why was something this heavy put into the ground? In September 1974, workers digging a tunnel on the Duling mound in Zhengzhou came upon it about six meters down. The mound sits roughly 300 meters outside the western wall of the early Shang city, which is one reason the find matters to historians studying how that city grew. The vessel did not come alone. A larger square ding, about a meter tall and now in the National Museum of China, was found with it, and a cattle skeleton lay among the remains. Some archaeologists have suggested that the group may have been linked to ritual sacrifice, but that idea is a hypothesis, not a proven fact. What the find does establish is the scale of the effort. Two dings this heavy required enormous quantities of metal and organized labor, whatever the reason for their deposit.","long":"Start with the corners. This bronze is built like a box rather than a bowl. Its body is square, its walls rise straight to a flat rim, and two upright ears stand on that rim. Underneath, four hollow cylindrical legs lift the vessel off the ground. The Chinese name for this type is ding, a ritual vessel used in the Shang dynasty to hold food offered during ceremonies.\n\nThis is the Duling square ding, made in the early Shang period, around 3,400 years ago. It stands about 87 centimeters high, its mouth measures roughly 61 centimeters on each side, and it weighs about 64 kilograms. Shang bronze was cast in sections of clay mould that were then assembled, and a vessel this size needed a large quantity of metal and many skilled, coordinated workers.\n\nLook at the decoration. The upper belly carries a taotie, a fierce mask with staring eyes, a motif that appears across Shang bronzes. Small raised knobs called nipple bosses cover the sides and lower body, breaking up the surface in an ordered pattern. Scholars debate what the taotie represented, and the purpose of the knobs is also uncertain. What is clear is that the surface was planned with care, so the vessel rewards a slow walk around it.\n\nIts discovery is as remarkable as its form. In September 1974, workers digging a tunnel on the Duling mound in Zhengzhou reached two square dings about six meters underground. The mound sits roughly 300 meters outside the western wall of the early Shang city. The larger of the pair, about a meter tall, is now in the National Museum of China. This smaller one is held by the Henan Museum. Accounts of who first spotted the vessels differ.\n\nThat setting raises the question of purpose. A cattle skeleton was found together with the pair, and some archaeologists have suggested that the group may have been connected to royal sacrifice. That remains a hypothesis, not a settled conclusion. The find also feeds a larger debate about Zhengzhou itself. Scholars still argue about which early Shang ruler, if any, held court here, so the vessel is evidence in an argument that is still open.\n\nWhatever its exact role, the Duling ding shows how far Shang bronze-casting had come. Circle it slowly, and notice how the square corners sharpen the whole form."}},{"museum_id":"henan","language":"en","id":"henan-07","position":6,"title":"Jade-Hilted Iron Sword","category":"Jade, Gold & Weapons","subtitle":"玉柄铁剑","artist":null,"facts":[{"label":"Period","value":"Late Western Zhou (c. 8th century BCE)"},{"label":"Type","value":"Weapon (jade and iron)"},{"label":"Material","value":"Iron blade; bronze hilt core inlaid with turquoise; Hetian jade hilt"},{"label":"Size","value":"Length 34.2 cm; hilt 12.2 cm"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/bwzl/jxysyhjsqjytzgygbz/jyhy/article2ff8d5d4e3a44448b3233e8c57835a1d.html","image":null,"guide":{"short":"Start with the hilt, because it holds the surprise. It looks like a solid jade handle, but it is an assembly. Two hollow sections of greenish nephrite, cut from Hetian jade in China's far west, slide together over a bronze core, and small copper pins lock them in place. Turquoise strips are set into the bronze and into the top of the pommel. Now look at the blade. It is iron, and iron was far rarer than bronze in Western Zhou China. The blade is forged onto the bronze core, so the three materials meet in one continuous object. This sword came from tomb M2001 at the Guo state cemetery in Sanmenxia, Henan, excavated in 1990. Iron, bronze, and jade together make a weapon that was meant to impress as much as to fight.","expansion":"The blade is where the sword earns its place in history. Analysis by researchers at the University of Science and Technology Beijing identified the iron as bloomery carburized steel, meaning it was smelted and worked by people rather than taken from a meteorite. If that reading holds, this is among the earliest scientifically confirmed examples of artificial iron in China, and it pushes the country's iron history back by more than a century. Scholars are cautious, though. Some suggest the blade, hilt, and core were made separately and joined with lacquer, but that idea has not been tested scientifically. Ask yourself why a weapon with such costly parts was buried in a Guo lord's tomb. Prestige is the most likely answer, but the sword's exact meaning remains open.","long":"Most visitors notice the jade first, and they are right to. The handle is made of greenish nephrite, the stone known as Hetian jade, carved into two hollow sections that slide together over a bronze core. Look closely and you will see thin strips of turquoise set into the bronze and the top of the pommel. The fit is careful rather than showy. Copper pins pass through small holes on each side to lock the parts together, so the jade is held mechanically rather than hidden under decoration.\n\nThe blade is the real surprise. It is iron, forged onto the bronze core, and it came from tomb M2001 at the Guo state cemetery in Sanmenxia, Henan, excavated in 1990. Guo was a Western Zhou state, and this tomb is linked to a Guo lord known as Guo Ji. In the late Western Zhou, bronze carried the prestige. Ritual vessels and weapons for the powerful were typically cast in bronze, while iron was far scarcer. A sword with an iron blade in a lord's tomb therefore stands out.\n\nAnalysis of the blade, reported by researchers at the University of Science and Technology Beijing, identified it as bloomery carburized steel, a product of artificial smelting rather than meteorite iron. If that identification holds, the sword is one of the earliest scientifically confirmed examples of iron made by human hands in China, and it pushes the country's iron history back by more than a century. Scholars are careful here, however. The cemetery's chronology is still debated, and the cemetery as a whole runs from the late Western Zhou into the early Spring and Autumn period. Some researchers also suggest the blade, hilt, and bronze core were made separately and joined with lacquer, an idea not yet tested in a laboratory.\n\nWhat does the sword mean? The combination of materials suggests it was meant to advertise rank as much as to fight. It may have signaled the political and military power of its owner, but that reading is an interpretation, not a documented fact. What is certain is that the object brings stone, copper, and iron into one weapon, and asks you to consider which of them the owner valued most."}},{"museum_id":"henan","language":"en","id":"henan-08","position":7,"title":"Four Spirits and Clouds Mural","category":"Murals","subtitle":"四神云气图壁画","artist":null,"facts":[{"label":"Period","value":"Early Western Han (c. 2nd century BCE)"},{"label":"Type","value":"Tomb mural"},{"label":"Material","value":"Pigment on a wall surface"}],"object_url":null,"image":{"src":"/images/paintings/henan-08.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Four_Deities_in_Clouds,_Western_Han_Tomb_Mural_Painting.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"Look up at this painting. It was made for the ceiling of a royal tomb chamber, and its ground is a deep cinnabar red, a mineral pigment made from mercury sulphide. Out of that red field a great dragon coils through the centre, while a vermilion bird hovers above and a white tiger crouches below. Painted clouds fill the spaces between them, so the whole scene reads as a sky. These animals are the four directional creatures of Chinese cosmology, which give the mural its title, Four Spirits and Clouds. Made in the early Western Han dynasty, around the second century BCE, it is described by museum sources as one of the earliest and largest tomb murals found in China. Its survival is remarkable: the painted plaster was carefully cut from its tomb and brought to Henan Museum, where it is displayed today.","expansion":"This mural was never meant to decorate a house or a temple. It belonged to a royal tomb of the Liang kingdom, a Western Han state ruled by princes of the Liu family, whose burial was cut into the rock of Mangdang Mountain near Yongcheng in Henan. Museum accounts link the tomb to King Gong of Liang, Liu Mai, but other sources name King Xiao, and some name no occupant at all, so the identity is still disputed. The tomb's design made such painting possible. One account describes a shift in royal tombs from vertical shaft graves to horizontal cave chambers, which gave painters more wall and ceiling space. The mural is painted in red, white, green and black pigments on plaster, and because it covers a ceiling, visitors inside the chamber would have looked straight up at it.","long":"Begin with the ceiling. A painting like this is easy to picture on a wall, but this one was laid across the top of a burial chamber, so anyone standing inside the royal tomb would have looked straight up into it. The ground is a deep cinnabar red, made from a mineral pigment that gives the whole field its warmth. Out of that red emerge the four directional creatures of Chinese cosmology. A dragon, its body twisting through the centre, dominates the scene, its tongue curling around a strange hybrid beast. Above it a vermilion bird, the guardian of the south, pecks at one of the dragon's horns, while below a white tiger holds a long flower in its mouth. The fourth figure is usually identified as the Black Tortoise, though its form does not match that creature neatly, and scholars have not fully settled the question. Painted clouds fill the gaps among the animals, so the whole composition reads as a sky.\n\nSetting matters as much as the image. The tomb belonged to the Liang kingdom, a Western Han state ruled by princes of the Liu family, and it was cut into the rock of Mangdang Mountain near Yongcheng in Henan. Museum accounts associate the tomb with King Gong of Liang, Liu Mai, but other sources name King Xiao, and some name no occupant at all. That uncertainty matters, because the identity of the person buried here shapes how we read the painting's rank and purpose. The dating to the early Western Han, around the second century BCE, is consistent across the sources I checked. The image itself was painted with mineral pigments in red, white, green and black on plaster.\n\nIts survival is the other story. In the late 1980s the painted plaster was carefully cut out in its original form and transferred to the Henan Museum, where it now stands among the institution's celebrated treasures. Museum publications describe it as one of the earliest and largest tomb murals found in China. Standing before it, you are looking at a painted sky that was once sealed underground, and that now survives where visitors can study it at close range."}},{"museum_id":"henan","language":"en","id":"henan-09","position":8,"title":"Ru Ware Sky-Blue Glazed Carved Goose-Neck Vase","category":"Ceramics & Pottery","subtitle":"汝窑天蓝釉刻花鹅颈瓶","artist":null,"facts":[{"label":"Period","value":"Northern Song dynasty (960–1127)"},{"label":"Type","value":"Ceramic (Ru ware)"},{"label":"Material","value":"Porcelain with sky-blue glaze over a greyish-buff body"},{"label":"Size","value":"Height 19.5 cm; mouth diameter 5.6 cm; foot diameter 8.2 cm"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zpjc/cq/article23f85aa418494272a448ad9fceced19e.html","image":{"src":"/images/paintings/henan-09.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:汝窑天蓝釉刻花鹅颈瓷瓶.png","license":"CC BY-SA 4.0","author":"陳寅恪"},"guide":{"short":"Let the color reach you first. This slender vase is covered in a sky-blue glaze, clear and glossy, the shade of a sky after rain. It is a Ru ware piece from the Northern Song dynasty, standing just under twenty centimetres tall. Its outline is a gentle S-curve: a flared mouth, a long thin neck, and a rounded belly above a small foot. Look closely at the neck and belly. Sprays of lotus are carved into the body, but they do not sit on the surface. They show faintly beneath the blue, appearing and fading as the light shifts. Chinese connoisseurs prized this shade most highly, and only a few sky-blue Ru pieces survive. This one was excavated in 1987 at Qingliangsi village in Baofeng County, Henan. Give it a slow look, and it rewards you.","expansion":"Now turn the vase over, because the foot holds a clue to how it was made. The base is bare of glaze, and the clay beneath has a greyish tone, with fine grains of sand stuck to it. Those grains suggest the vase was fired standing on small supports rather than directly on the kiln floor. Potters usually left the foot unglazed, since glaze would fuse to whatever it touched. Look at the surface too. A fine web of crackle spreads evenly across the glaze, catching the light in a pattern of hairline lines. Then comes the harder question: when was it made? Estimates for the kiln's active years range from roughly 1086 to 1125, and specialists still debate the exact span. Some link the kiln to the reign of Emperor Huizong, though that connection remains open to discussion. Keep that uncertainty in mind as you look at the blue.","long":"Start with the color, because it is what most visitors notice first. The glaze over this vase is a clear, pale sky-blue, even and glossy, the shade that Chinese connoisseurs once called the most precious of all. This is Ru ware, a porcelain made at the Qingliangsi kiln in what is now Baofeng County, Henan, during the Northern Song dynasty. The vase is a Ru official-kiln piece, and its outline is a relaxed S-curve: a flared mouth, a long slender neck, a rounded belly and a small foot. Look carefully at the neck and belly. Sprays of lotus, carved into the body, show faintly through the glaze, as though the design floats beneath the surface and appears only when light moves across it. Museum text says this hidden lotus design is not seen on transmitted Ru pieces.\n\nTurn it over and the story becomes technical. The foot ring is bare of glaze, the clay beneath is greyish, and tiny grains of sand cling to it. Those grains show the vase was fired standing on small supports rather than directly on the kiln floor. Such traces are how specialists reconstruct the work of the potters who made it.\n\nThe kiln behind the vase was a court enterprise. Ru ware is often described as perhaps the first official ware commissioned by the imperial court. Most accounts say the finest pieces were kept for the palace, and only rejected pieces reached a wider market. Its productive life was brief. Estimates of how long it operated range from about twenty to about forty years, and most tie its output to the reign of Emperor Huizong. Scholars still debate the exact dates, and production is generally linked to the upheavals of the 1120s.\n\nThis vase was not found in a tomb or a palace. It was excavated in 1987 at the kiln site itself, in Qingliangsi village. We do not know who handled it or where it stood. One scholarly study groups goose-neck vases among display wares, which suggests a decorative role, but its original use is not recorded and should not be assumed.\n\nIts importance today lies in its rarity. Only a small number of sky-blue Ru pieces are known from collections, and the museum counts this one among its nine treasures. Its color, shape and hidden carving reward patient looking. Take your time with it."}},{"museum_id":"henan","language":"en","id":"henan-10","position":9,"title":"Painted Pottery Double-Linked Vessel","category":"Ceramics & Pottery","subtitle":"彩陶双连壶","artist":null,"facts":[{"label":"Period","value":"Neolithic, Yangshao culture (c. 3500–3000 BCE)"},{"label":"Type","value":"Painted pottery drinking vessel"},{"label":"Material","value":"Fine red earthenware with black painted decoration over a red slip"},{"label":"Size","value":"Height 20.1 cm; base diameter 5 cm"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/bwzl/yyhxzzjd/cpsx/article02dad096e98349b19ed9feaa402f6667.html","image":{"src":"/images/paintings/henan-10.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Yangshao_Culture_Painted_Pottery_Twin_Flasks.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"Look closely at this vessel and you are looking at two jars joined at the belly. It is a painted double-linked jar from the Yangshao culture, unearthed in 1972 at Dahecun, a Neolithic site in Zhengzhou. The two bodies are nearly identical, set side by side and connected by an oval opening. The surface is fine red earthenware, covered with black painted bands of parallel lines and clusters of short strokes. Archaeologists first found the two halves separated, then realised they fitted together exactly. The museum reads it as a drinking vessel for shared ceremonies: two people could each hold one body and drink at the same moment. Standing about twenty centimetres tall, it is small enough for two hands, and its form seems built around sharing.","expansion":"The painted pattern rewards a second look. The black marks come in two arrangements: long horizontal bands, and groups of three short strokes, drawn upright on one body and slanted on the other. Some researchers suggest the difference stands for two separate groups, perhaps two communities brought together. A former director of the Dahecun site museum has offered a version of this reading, in which rival groups reconciled by drinking from the same vessel. It is a compelling story, but it remains an interpretation, and the pottery carries no text that confirms it. The Chinese cross-cup wine toast, jiaobei jiu (交杯酒), is sometimes mentioned alongside the vessel, but scholars have not established any direct link. What the evidence firmly supports is the craft: two bodies of almost identical shape, joined and painted with a controlled design that has survived more than five thousand years underground.","long":"Start by looking at the shape. What appears to be one jar is in fact two, rising side by side from a shared base and joined at the belly by an oval opening. Each body mirrors the other, and the whole piece stands just over twenty centimetres tall, small enough to hold in two hands. This is a painted double-linked jar of the Yangshao culture, the Neolithic tradition that flourished along the middle Yellow River. Its fine red earthenware was coated with a red slip and decorated in black: coarse horizontal lines, and groups of short strokes, some drawn upright and some slanted.\n\nIts discovery is part of its story. It was unearthed in 1972 at Dahecun, a settlement site in Zhengzhou. The two halves were found apart. Only when they were reconstructed did archaeologists see that they fitted together exactly, which suggests the two bodies were made as a matched pair.\n\nSo what was it for? The Henan Museum reads it as a drinking vessel, perhaps used on ceremonial occasions, in which two people each held one body and drank at the same moment. That reading fits the design, since the shared opening links the two sides into a single object. Some researchers go further, proposing that the contrast between upright and slanted marks stands for two different groups, and that the vessel marked a pact between them. It is an appealing idea, but it is an interpretation. No inscription on the pot confirms it, and later practices such as the cross-cup wine toast are sometimes linked to vessels like this without proof.\n\nWhat the evidence firmly supports is the craftsmanship. Shaping two matching bodies, joining them, and applying an even black pattern across curved surfaces demanded real skill with clay and fire.\n\nIt matters today because it asks a question that pottery can only partly answer: how did people in the Neolithic mark a shared bond? This vessel offers a clue, not a full answer, and that is exactly why it rewards careful looking."}},{"museum_id":"henan","language":"en","id":"henan-11","position":10,"title":"Ding of Prince Ziwu","category":"Bronzes","subtitle":"王子午鼎","artist":null,"facts":[{"label":"Period","value":"Spring and Autumn period (770–476 BCE)"},{"label":"Type","value":"Bronze ritual vessel (ding)"},{"label":"Material","value":"Bronze"}],"object_url":null,"image":{"src":"/images/paintings/henan-11.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:“王子午”青铜鼎（附匕）03671.jpg","license":"CC BY-SA 4.0","author":"Cangminzho"},"guide":{"short":"Start with the shape. This bronze is a ding, a tripod vessel used to cook meat for sacrifice, and its heavy body rests on three legs. The Ding of Prince Ziwu was made in the Spring and Autumn period for the Chu kingdom, a powerful southern state whose bronze style developed its own character. What makes it stand out is its inscription. Cast inside the vessel, the text runs to more than eighty characters, unusually long for a ritual cauldron. It says the ding was made for ancestral sacrifices and for ceremonies that sealed alliances. Measure it against your own height: at just under half a meter tall, it is a substantial pot. Picture it on an ancestral altar, steaming with meat, and you begin to understand why a cauldron could carry so much weight.","expansion":"Now turn to where it was found. In 1978, excavators opened a Chu tomb at Xiasi, in Xichuan county, Nanyang, in southwestern Henan. Today that landscape lies within the Danjiang reservoir area of the South-to-North Water Diversion Project, a reminder of how much history can sit beneath modern engineering. The inscription names the maker as Prince Ziwu, and the museum's account links him to a son of King Zhuang of Chu. That attribution is traditional, so it is worth holding loosely. Some accounts also describe a set of seven ding of the same shape in graded sizes, though sources disagree on that count. Finally, one scholarly account notes that the inscription uses bird-and-worm script, a decorative style more often seen on weapons.","long":"Imagine a cauldron that could cook a sacrificial meal and, at the same time, announce who had commissioned it. That is the Ding of Prince Ziwu, one of the most important bronzes from the southern kingdom of Chu. Start with its shape. It is a ding, a tripod vessel with a lid and three legs, the kind of cooking pot used in Shang and Zhou ritual. Its body stands just under half a meter high, roughly 49 centimeters, and measures about 58 centimeters across the mouth, which would have made it a serious object to lift and to fill.\n\nDing were not kitchen equipment in the ordinary sense. Meat cooked in them was offered to the ancestors, and scholars generally link the number and size of ding a family owned to its rank. This one is an unusually ambitious example. Its inscription, cast inside the vessel, runs to more than eighty characters. As the museum describes it, the text records that the ding was cast for ancestral sacrifices and for ceremonies that sealed alliances. It also claims that the maker's benevolent rule has earned the love and respect of the people of Chu.\n\nThe vessel dates to the Spring and Autumn period, when Chu, a large state along the middle Yangtze and Han rivers, was expanding and developing a bronze style of its own. Prince Ziwu is traditionally identified as a son of King Zhuang of Chu, an attribution worth holding loosely.\n\nThe ding was excavated in 1978 from a tomb at Xiasi in Xichuan county, Nanyang, in southwestern Henan. Today the site lies within the Danjiang reservoir area, part of the South-to-North Water Diversion Project, so the find is a reminder of how much history can sit beneath modern engineering. Some accounts report that the tomb held a set of seven ding of the same shape in graded sizes, but the exact count, and the number of characters in the inscription, are given differently in different sources.\n\nThe inscription is also written in bird-and-worm script, a decorative style that one scholarly account notes is more often found on short weapon inscriptions than on vessels like this. Seeing it today, you are looking at a cooking pot designed to speak as much as to feed."}},{"museum_id":"henan","language":"en","id":"henan-12","position":11,"title":"Wangsun Gao Bell Set","category":"Musical Instruments","subtitle":"王孙诰编钟","artist":null,"facts":[{"label":"Period","value":"Spring and Autumn period (c. 6th century BCE)"},{"label":"Type","value":"Bronze musical instrument (set of yong bells)"}],"object_url":"https://www.chnmus.net/ydgyt/collection/details.html?id=7100016422079696896","image":{"src":"/images/paintings/henan-12.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sun_Gao_Bianzhong,_picture4.jpg","license":"CC0","author":"Huangdan2060"},"guide":{"short":"Before you stands a set of twenty-six bronze bells, each made to be struck and each made to sing. Archaeologists call them yong bells, after the hollow stem on top. What makes this set remarkable is that every bell sounds two pitches, depending on where it is struck. According to the Henan Museum, striking the front and side areas together produces a harmonious third. Across the set, the range spans about four and a half octaves. The museum calls it the largest and most numerous Spring and Autumn bell set yet found in China. It came from a Chu tomb at Xichuan in Henan, excavated in 1978. Listen for the two voices in each bell, and you begin to hear what these bells were built to do.","expansion":"The bells carry an inscription, which the museum records as 113 characters. It names the maker as Wang Sun Gao, and says the bells were made to delight the king of Chu, honored guests, fathers and elder brothers, and officers, for ten thousand years. Those words point to ceremony and feasting, the settings the museum associates with this kind of music. But the inscription is contested. A recent online essay by a single author argues that its text was copied from a bell now in San Francisco, and that the characters were added in modern times. That essay is unfinished and has not been peer reviewed, and it does not claim the bells themselves are fake. Treat the name Wang Sun Gao as the museum's reading, and the question as still open.","long":"Look first at the number. Twenty-six bronze bells, each a yong bell named for the hollow stem on its top. Visitors tend to stop at the shapes, but the real story is in the sound. According to the Henan Museum, each bell is cast to sound two pitches, one from its front face and one from its side, and striking both together produces a harmonious third. Across the set, the range spans about four and a half octaves. For a sixth-century BCE instrument, that is a remarkable span, and it explains why the museum describes the set as the largest, most numerous, and best-sounding bell set of the Spring and Autumn period so far found in China. Those are the museum's own superlatives, and they rest on the instruments themselves.\n\nThe bells were excavated in 1978 from a tomb at Xiasi, in Xichuan county, Henan. The tomb is a Chu tomb. Chu was a southern state whose core lay in the middle Yangzi region, and its bronzes and musical habits differ in character from those of the northern courts. Bell sets like this one were markers of rank, and the number of bells and their range signaled how important their owner was. The museum says this set was played in ritual and banquet settings.\n\nThe bells also carry an inscription of 113 characters. It names the maker as Wang Sun Gao and says the bells were made to delight the king of Chu, honored guests, fathers and elder brothers, and officers, for ten thousand years. Those words suggest a public world of ceremony and feasting, where the music was meant to be heard by many people.\n\nBut the inscription is contested. A recent online essay by a single author argues that its text was copied from a bell now in San Francisco, and that the characters were added in modern times. That essay is unfinished and has not been peer reviewed, and it does not claim the bells themselves are fake. Scholars also debate who owned the tomb. The name Wang Sun Gao and the identity of the owner therefore remain open questions.\n\nSo look at the set as a working instrument, one that was designed to be played. The maker's name may be disputed, but the sound the bells were built to make is not."}},{"museum_id":"henan","language":"en","id":"henan-14","position":12,"title":"Jade Burial Suit with Gold Thread","category":"Jade, Gold & Weapons","subtitle":"金缕玉衣","artist":null,"facts":[{"label":"Period","value":"Western Han dynasty (206 BCE–25 CE)"},{"label":"Type","value":"Jade funerary garment"},{"label":"Material","value":"Jade plaques joined with gold wire"}],"object_url":null,"image":{"src":"/images/paintings/henan-14.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Jade_Suit_Sewn_with_Gold_Thread.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Look closely at this burial suit and you will see that it is not carved from a single stone. It is made of 2,008 separate jade plaques, most of them a deep blue-green, joined together with fine gold wire. Its Chinese name, 金缕玉衣, jīnlǚ yùyī, means \"jade garment with gold thread.\" Makers shaped each plaque and stitched them into a body-shaped garment in five parts: a head covering, a jacket, trouser legs, hands and feet. The plaques differ in size, shape and colour, fitted to follow the head, limbs and joints. The gold thread holds the whole structure together. Han-period jade suits were funerary garments for emperors and senior nobles, made to protect the body after death. This example was excavated in 1985 from a Western Han tomb at Xishan, in Yongcheng, Henan. Look at the joins, where the making is most visible.","expansion":"Look at the small objects too. The Henan Museum account lists a jade pig to be held in the hand, a jade cicada placed in the mouth, and jade plugs for the ears and nose. The cicada is often read as a symbol of rebirth, but that is an interpretation, not an inscription, and scholars read the pig differently. Together these pieces show that the suit was meant to work as part of a complete burial set, not as clothing alone. The owner is also debated. Some accounts tie this tomb to the Liang kingdom, a princely state in this region, and others name a particular prince. Neither identification has been confirmed. Much of what we know about who was buried here depends on what excavators recorded at the time.","long":"Begin with the colour. Where you might expect a single carved figure, you find a garment built from 2,008 separate jade plaques, most of them a deep blue-green, with others in lighter and darker tones. Each plaque is a small piece of shaped jade, and together they cover the head, the jacket, the trousers, the hands and the feet. The plaques are joined with gold wire that passes through holes in each piece and holds the whole structure together. The suit was made to fit a human body, and it still keeps that shape.\n\nIts Chinese name, 金缕玉衣, jīnlǚ yùyī, means jade garment with gold thread. The thread matters. Han tombs also produced suits joined with silver or silk, and the choice of thread is generally read as a sign of rank. Gold was the costliest of these materials.\n\nThe suit was a funerary garment. Museum accounts describe such suits as burial garments for Han emperors and senior nobles, made to protect the body after death. Some sources add that the jade was believed to help the deceased reach immortality. That is a belief about the afterlife, not a demonstrated outcome, so it is best held as a belief. Its job was to protect the body.\n\nLook also at the small objects that accompanied the suit. The Henan Museum account lists a jade pig to be held in the hand, a jade cicada placed in the mouth, and jade plugs for the ears and nose. The cicada is often read as a symbol of rebirth, but that reading is an interpretation rather than something written on the object. Scholars have offered different views on the pig.\n\nThis suit was excavated in 1985 from a Western Han tomb at Xishan, in Yongcheng, Henan. Its owner is not secure. Some accounts link the tomb to the Liang kingdom, a princely state in this region, and some name a particular prince. Neither identification has been confirmed in the sources I could consult, so the person who wore the suit remains uncertain.\n\nWhy does it deserve attention today? It shows the labour and wealth a princely family could direct toward the afterlife, and the problem of fitting hard stone to the shape of a human body. Stand close, follow one gold join from plaque to plaque, and you can see the engineering that holds an entire garment together."}},{"museum_id":"henan","language":"en","id":"henan-15","position":13,"title":"Sancai Horn-Shaped Cup","category":"Ceramics & Pottery","subtitle":"三彩角形杯","artist":null,"facts":[{"label":"Period","value":"Tang dynasty (618–907)"},{"label":"Type","value":"Burial object (earthenware)"},{"label":"Material","value":"Earthenware with yellow, green and white sancai glaze"},{"label":"Size","value":"Length 14 cm; height 7.0 cm; mouth diameter 7.0 cm"}],"object_url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512155217003765138","image":{"src":"/images/paintings/henan-15.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Tri-Color_Glazed_Pottery_Cup_Shaped_of_Horn.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Start with the head. At the upper end of this curved, horn-shaped cup, an animal turns its head back over its shoulder, a flower sprig held in its beak. That sprig becomes the handle. Now look at the surface. Yellow, green and white glazes flow over the whole body, and scrolling grass patterns wind across it. The shape travelled a long way to get here. Horn-shaped drinking vessels, called lai tong (来通) in Chinese, trace back to Greek rhyta and reached China along the Silk Road. Tang craftsmen took that foreign silhouette and dressed it in their own colours. At about fourteen centimetres long, it fits in one hand. Some visitors see a peacock, which gave the cup its nickname. Others read a dragon. The museum treats both readings as open, so decide for yourself.","expansion":"Now consider where it was found and why it was made. In 1976, excavators at Houwangzhuang, on the western outskirts of Zhengzhou, recovered this cup. The museum classifies it as a mingqi (明器), a burial object made to accompany the dead. It was a grave good, not a piece for the dinner table. The museum dates it to the Tang and compares it with pieces from tombs of the Gaozong and Zhongzong reigns, roughly the later seventh to early eighth century. Sancai glazes are typically lead-based, which is why the colours sit so softly on the earthenware body. Compare it with a small bird-shaped rhyton in the Metropolitan Museum of Art, made in the seventh or eighth century. It shows the same basic idea: a foreign drinking vessel reworked in Tang glaze.","long":"Pick the cup up with your eyes first. It is curved like a horn, about fourteen centimetres long and seven centimetres high, with an oval mouth at the wide end. Near the top, an animal turns its head back over its shoulder, a flower sprig held in its beak, and that sprig forms the handle. The whole earthenware body is covered in yellow, green and white glaze, with scrolling grass patterns winding across it. The colours are bright and the scale is intimate. It was made to sit comfortably in the hand.\n\nThe silhouette is the real story. Horn-shaped drinking vessels, known in Chinese as lai tong (来通), trace back to the Greek rhyton, and they reached China along the Silk Road during the Northern and Southern Dynasties. Chinese potters took that foreign form and rebuilt it in their own clay and glazes. The result looks foreign at a glance and Chinese on closer inspection, and that mix is what makes it worth a second look.\n\nThe head is the most debated detail. Many people see a peacock, and that reading gave the cup its nickname, the peacock cup. The museum also considers a dragon's head equally possible and leaves the question open. It is a useful reminder that an animal on a Tang object does not carry one fixed meaning. Treat the head as a question rather than an answer.\n\nIts purpose is more certain. The museum classifies it as a mingqi (明器), a burial object made to accompany the dead. It was not made for everyday drinking, even though its shape suggests a drinking vessel. It was excavated in 1976 at Houwangzhuang, on the western outskirts of Zhengzhou in Henan. The museum compares it with cups from tombs of the Gaozong and Zhongzong reigns, which places such pieces roughly in the later seventh and early eighth centuries. The dating rests on that comparison, because the cup itself carries only the broad label Tang.\n\nSo why does it deserve attention today? In one small vessel you can see the Tang world's appetite for foreign shapes and its confidence in remaking them. Look at the grass scrolls and the turned head, and you are looking at a Chinese answer to a Greek idea."}},{"museum_id":"henan","language":"en","id":"henan-16","position":14,"title":"Standing Dog with Green Glaze","category":"Ceramics & Pottery","subtitle":"绿釉陶立狗","artist":null,"facts":[{"label":"Period","value":"Han dynasty (206 BCE–220 CE)"},{"label":"Type","value":"Pottery burial object"},{"label":"Material","value":"Earthenware with green glaze"}],"object_url":null,"image":{"src":"/images/paintings/henan-16.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Green_glazed_pottery_standing_dog,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Start with the posture. This dog stands upright on four legs, and its body is covered in a glossy green glaze that gives plain clay a bright, glassy finish. The title, 绿釉陶立狗, tells you the essentials: green glaze, pottery, and a dog standing up.\n\nBut this is not a pet to be walked. It is a mingqi, or 明器, often translated as \"spirit utensil.\" Such pieces were made for tombs rather than homes. Han families placed models of animals, household goods, and everyday life in graves, so the dead would have what they needed in the afterlife. A dog was among the most familiar of those companions, and its role was simple: to keep its owner company in the next world.\n\nThe glaze does much of the decorative work, and the upright stance does the rest.","expansion":"Why would a family spend on a glazed figure rather than leave a plain one? In the Han dynasty, burial goods were no longer reserved for emperors and nobles alone. As government service spread to a wider class of officials, more households could afford to furnish a tomb with models of the life they hoped to continue. Clay made this possible: it was plentiful, easy to shape, and suited everything from rough earthenware to glazed pieces.\n\nThe green glaze is the other half of the story. Han green glazes were typically lead-based, fused in the kiln into a glassy coating. Glazing set certain pieces apart from plain earthenware.\n\nA word of caution. Whether this particular figure uses a lead glaze, and where and when it was buried, has not yet been confirmed against the museum's own record.","long":"Most visitors would take a figure like this for a toy or a decorative animal. Look closer. Its title, 绿釉陶立狗, describes a dog standing upright, made of pottery and covered in a green glaze. Those few characters point to a whole way of thinking about death in the Han dynasty, which lasted from 206 BCE to 220 CE.\n\nThe dog is a mingqi, or 明器, often translated as \"spirit utensil.\" The term refers to objects made for burial rather than daily use. Han families placed in their tombs replicas of what the deceased had known in life: farm buildings, livestock, household tools, and attendants. The models were meant to supply the soul with what it needed. A dog, one of the most familiar companions in a household, was a natural member of that group. Its role in the tomb was to keep its owner company in the next world.\n\nMaking such figures was economical. Clay was abundant and easy to shape, so it could serve families across a wide social range. What set some pieces apart was glaze. Han green glazes were typically lead-based, applied to the surface and fired until they formed a bright, glassy skin over the earthenware. The glaze gave the figure a richer appearance than plain pottery, even though it was made from the same humble clay.\n\nWho buried such objects? The Han period saw power spread beyond the emperor and the aristocracy. As government service reached a broader class of officials, more households could afford to furnish a tomb in this way. Tomb goods became a way of signalling status and securing comfort in death, and a glazed model of a dog could express both loyalty and a family's means.\n\nWe should be careful here. The record for this particular piece has not yet been checked against the museum's collection data, so its precise date within the Han, its findspot, and whether its glaze is lead-based all remain to be confirmed. What we can say with confidence is that it belongs to a tradition in which everyday animals and objects, shaped in clay, were given a second life underground.\n\nThat is perhaps the most affecting thing about it. A companion that was familiar in life was modelled again in clay and glaze, so that its company could continue into the afterlife."}},{"museum_id":"henan","language":"en","id":"henan-17","position":15,"title":"Pottery Stove with Four Spirits Decoration","category":"Ceramics & Pottery","subtitle":"四神画像陶灶","artist":null,"facts":[{"label":"Period","value":"Han dynasty"},{"label":"Type","value":"Pottery burial object"},{"label":"Material","value":"Pottery (fired clay)"}],"object_url":null,"image":null,"guide":{"short":"Look closely at the small clay stove in front of you. It was never meant to cook a meal. Han tomb builders placed miniature household goods, called míngqì (明器), or spirit articles, in tombs so the dead would be provided for in the afterlife. This model kitchen, with its cooking holes and smoke vent, is one such provision. What sets it apart is the decoration pressed into its surface. The Four Spirits, the Azure Dragon, White Tiger, Vermilion Bird and Black Tortoise, guarded the four directions of the sky. Here, a Black Tortoise, or Xuanwu (玄武), is molded on either side of the stove door, and a Vermilion Bird decorates the back wall. Find them, then imagine the cook these guardians were meant to protect.","expansion":"Now look at the rest of the stove. The decoration goes beyond the four directions. Above the door, an eagle is molded into the clay. On the side walls, a winged figure rides a dragon, and a warrior fights a tiger. Fish appear on the sides of the cooking top. Their meaning is open to interpretation. Some scholars relate such imagery to ideas of ascent and immortality, while others focus on the stove's everyday role. The practical details are clear enough. Two fire holes hold cauldrons, and a round vent beside them drew smoke away from the cook. Han households are known to have honored a Stove God, 灶神, near the hearth, so cooking here may have carried spiritual meaning too. Whether this stove was made with that deity in mind cannot be proven.","long":"Begin with the front. Between two molded creatures, a small semicircular opening leads into the firebox, and on either side of it a Black Tortoise, or Xuanwu (玄武), is pressed into the clay. Now picture a working kitchen from the Han period. A fire would have burned beneath cauldrons set into the cooking top, and a vent would have carried smoke away from the cook. This model copies that everyday object closely, with two fire holes and a round smoke vent beside them. Yet it was not made for cooking. Han tombs held miniature household goods, called míngqì (明器), or spirit articles, made so the dead would be supplied in the afterlife, much as the living were. A model kitchen was a way of making sure the dead would never go hungry. The Four Spirits, the Azure Dragon, White Tiger, Vermilion Bird and Black Tortoise, guarded the four directions, and by the Han they were a common way of picturing the sky and the space around a building. The Black Tortoise appears by the door, and the Vermilion Bird is placed on the back wall, opposite the entrance. The designer does not stop at the four animals, however. The side walls show a winged figure riding a dragon and a warrior fighting a tiger. An eagle is molded above the door, and fish decorate the cooking top. Their meaning is open to interpretation. Some scholars relate imagery of ascent and immortality to scenes like these, while others focus on the stove's everyday role. Han households are known to have honored a Stove God, 灶神, near the hearth, so the cooking space carried spiritual meaning as well as practical use. Whether this stove was made with that deity in mind cannot be proven. What makes the object worth attention is the way it turns a kitchen into a small cosmos. Whoever made it did not simply reproduce a stove. Look again at the guardians around the door, then at the cauldron holes, and you are seeing a household's hope for the next world, fired in clay."}},{"museum_id":"henan","language":"en","id":"henan-18","position":16,"title":"Fu Yi Jue (Bronze Jue of “Father Yi”)","category":"Bronzes","subtitle":"父乙角","artist":null,"facts":[{"label":"Period","value":"Early Western Zhou"},{"label":"Type","value":"Bronze wine vessel (jue)"},{"label":"Material","value":"Bronze"},{"label":"Size","value":"Height 29 cm; mouth 20.3 × 9.8 cm"}],"object_url":"https://www.chnmus.net/content/redirect?id=512155913655553326","image":null,"guide":{"short":"Start with the lid. This bronze wine vessel from Henan Museum has a lid shaped like a roof ridge, topped by a small half-ring knob. On one side of the body, a half-ring handle ends in an animal head. Now look at the surface. Many bronzes of this age are crusted green, but this one is nearly black and glossy, close to old lacquer, with almost no corrosion. Three triangular feet lift the body, though one of them is a later replacement. Twelve characters are cast on the lid and twelve on the body, and the two texts match. They record a dedication to a father called 父乙, Fù Yǐ, which translates roughly as Father Yi. The inscription calls the vessel a precious ritual vessel. Its surface is decorated with animal faces, dragons, and cloud-and-thunder patterns, all packed into a small space.","expansion":"Now look at the inscription as a pair. The same twelve characters appear on the lid and on the body, so the two halves carry one message. That message is a dedication to a father named 父乙, and it calls the vessel a precious ritual vessel. The repetition matters because it makes the lid part of the inscribed object, not merely a cover. Then look at the feet. The replacement foot sits directly beneath the animal-headed handle. It tells you this vessel has a history after it was cast, because a part was replaced at some point, though the sources do not say when or by whom. Read the vessel as a document, not just a shape, and the feet become part of the story.","long":"Stand in front of this bronze wine vessel and start with its colour. Most bronzes of this age have turned green or crusty after millennia in the ground. This one is almost black and glossy, with barely any corrosion. The museum compares its surface to old black lacquer and notes that such a surface is uncommon among Shang and Zhou bronzes.\n\nIt is a jue, a type of wine vessel, about 29 centimeters tall. The lid rises into a shape like a roof ridge. The body flares at the mouth, pinches inward at the waist, and rests on three triangular feet. On one side, a half-ring handle ends in an animal head. Every section is decorated with animal faces, triangular patterns, dragons, and a cloud-and-thunder ground pattern, with raised ridges along the edges. The museum describes the decorative method as a three-layer technique, which suggests how the designs were built up in layers. One of the three feet, the museum notes, is a later replacement.\n\nThe most revealing part is the inscription. Twelve characters are cast on the lid and twelve on the body, and they match. Read together, they record a dedication to a father named 父乙, usually rendered Father Yi, and they describe the vessel as a precious ritual vessel. That wording ties the object to ancestral worship from the early Western Zhou, roughly three thousand years ago. The sources do not say how the vessel was used in ritual, so it is wise not to fill that gap with guesses.\n\nIts history is also unusual. In 1986, a group of fourteen bronzes was recovered from river silt near Xinyang, in southern Henan. A second, nearly identical cup was found with this one, and the museum holds this example. That near-twin matters, because it shows that the vessels were made as a set and then came out of the ground together.\n\nWhy does it deserve attention today? Because it can be read, not just admired. Its dark surface, its twelve matching characters, and its one replaced foot each tell a different part of its story. Look at it slowly, and it becomes a record of who it honoured and how carefully it was made."}},{"museum_id":"henan","language":"en","id":"henan-19","position":17,"title":"Sancai Lion-Shaped Pillow with Base","category":"Ceramics & Pottery","subtitle":"三彩狮形座枕","artist":null,"facts":[{"label":"Period","value":"Song dynasty"},{"label":"Type","value":"Ceramic"}],"object_url":"https://www.chnmus.net/content/redirect?id=7066681088168431616","image":{"src":"/images/paintings/henan-19.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20230217_Three-color_Porcelain_Pillow_in_Lion_Shape.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"Look at this object as a pillow first. Its title, 三彩狮形座枕, names a lion-shaped form on a base, and a pillow is a headrest, so whatever the lion looks like, its job was to support a sleeping head. The Henan Museum dates it to the Song dynasty, which lasted from 960 to 1279. Next, consider the word 三彩, sancai, which literally means three colours. It is a loose label. Scholars note that Song-period wares carrying this name are generally multicolour, low-temperature lead-glazed pieces, and the number three is not a count. As you walk around the lion, let the glaze, not the number, guide your attention. Notice how a sculpted animal becomes an everyday bedding object, serious in its form yet made for something as quiet as a night's sleep.","expansion":"The title's word, sancai, deserves a closer look, because the museum record does not settle how this piece should be described. Chinese scholars have long used the phrase Song sancai for multicolour wares of the Song period, yet one specialist study calls that usage imprecise and treats these wares as low-temperature lead-glazed objects. The museum files this one under ceramics, a broad category that does not say whether the body is porcelain or earthenware. The distinction is not pedantic. Lead glazes are fired at lower temperatures than porcelain glazes, so the body and surface tell different stories about how the piece was made. Until a material description is available, treat the body and glaze as open questions, and let your own eyes check the surface against the label.","long":"Start with the most basic fact about this object: it is a pillow, made to be slept on. Its title, 三彩狮形座枕, describes a lion-shaped form resting on a 座, a stand or base. The Henan Museum dates it to the Song dynasty, which lasted from 960 to 1279, and files it among its ceramics.\n\nThe word 三彩 needs care. It literally means three colours, but scholars point out that the label is applied loosely to Song-period wares. One specialist study describes these pieces as multicolour, low-temperature lead-glazed objects, and treats the name Song sancai as an imprecise habit. The number three is not a count. Think of the name as a family resemblance rather than a precise recipe.\n\nThe official record is also sparse. It gives the title, the period and the category, but not the dimensions, a material description, excavation details or a maker, so this guide will not supply them. Nor should we assume a meaning for the lion. The motif appears across Chinese art in Buddhist settings, imperial contexts and everyday objects, and its significance shifts with each. Without evidence from this piece's original setting, the safest reading is the simplest one.\n\nThat simple reading is useful. Notice how little it needs: no legend, no ritual, just a bed and a head. A pillow is a headrest, so the lion's form had to serve a sleeping head. The sculpted animal was not a figure standing beside a bed. It was the bed object itself, with enough weight and stability to hold the head through a night's rest. Imagine the object in use, and the decorative and the practical begin to fuse. That combination, a lion turned into something quiet and domestic, is what makes this pillow worth attention. Look at it as a tool first and a sculpture second, and its details will start to reveal how people actually lived with ceramics."}},{"museum_id":"henan","language":"en","id":"henan-20","position":18,"title":"White-glazed Lotus-Petal Bowl","category":"Ceramics & Pottery","subtitle":"白釉莲瓣碗","artist":null,"facts":[{"label":"Period","value":"Liao dynasty (916–1125)"},{"label":"Type","value":"Ceramic"},{"label":"Material","value":"White-glazed ceramic"}],"object_url":"https://www.chnmus.net/content/redirect?id=7066680004351889408","image":null,"guide":{"short":"Look at the wall of this bowl and you will find petals. Its sides are shaped like the petals of a lotus (莲瓣), each one swelling outward and curving back toward the foot, so a plain working bowl takes on the look of a half-open flower. The white glaze is worth noticing too. The bowl belongs to the Liao dynasty, the state founded by the Khitan people in the north, which governed a mixed population of Khitan, Han Chinese and others. Lotus motifs had a long life in Chinese art, most famously in Buddhist settings, but on an everyday bowl they may have been chiefly decorative. This was made to be used, washed and used again. Notice how the petals catch the light as you walk around it, and how their simple repetition gives the bowl its calm rhythm.","expansion":"Here is a question that has no settled answer: where was this bowl made? Liao territory covered much of northern China, Inner Mongolia and Manchuria, and its kilns produced white wares. Yet this bowl is in Henan, in the Central Plains, far south of the Liao heartland, and that distance sharpens the question. Scholars often connect Liao white porcelain with northern centers such as Ding in Hebei. They think white porcelain forms and techniques passed from these northern kilns to neighboring kilns during the Liao and Jin periods. So a bowl like this one may come from a Liao workshop, from a Ding-linked kiln, or from somewhere in between. Attribution here is a matter of evidence and argument. Treat the question as part of the bowl's story, because the answer changes what it tells us about how northern ceramic skills traveled.","long":"Begin with the wall beneath the rim. Run your eye around this bowl and you find a rhythm of petal-like forms, each one swelling outward and folding back toward the foot, until the whole vessel reads as a flower that has half opened. It is a simple thing to hold: a bowl for everyday use, made to be washed and used again. The lotus, though, has a long history in Chinese art. It rose to prominence through Buddhist temple decoration in the Tang period, and by the time this bowl was made, lotus petals were among the most familiar motifs on ceramics. A motif does not carry one fixed meaning from one century to the next, however. On a working bowl the petals may have been chiefly pleasing to the eye, or they may have carried a Buddhist resonance for the person who used it.\n\nThe glaze matters as much as the shape. White-glazed wares were a notable part of ceramic production in the north during the Liao dynasty, which lasted from the early tenth century to 1125. The Khitan people who founded Liao came from the steppe, and they governed a large population of Han Chinese farmers, artisans and officials. The state drew on the skills of older Central Plains workshops, and scholars often link Liao white porcelain to Ding, the famous kiln in Hebei. Ding forms and techniques seem to have passed to neighboring kilns during the Liao and Jin periods, so a bowl like this one belongs to a wider northern conversation about clay, glaze and taste.\n\nThat conversation also raises a question about this particular bowl. It is now in a museum in Henan, in the Central Plains far south of the Liao heartland. Was it made by a Liao workshop, by a kiln connected to Ding, or somewhere in between? Scholars weigh such questions against evidence. The answer shapes what the bowl tells us about how northern skills traveled.\n\nWhat, finally, does it reveal? A plain bowl from a northern state, shaped by a mixed population and by a long Buddhist and Chinese inheritance, shows how far these cultures had learned from one another. Its type points toward everyday use rather than court display, and it asks us to give a humble form real care. That is why it deserves a slow look today."}}]$seed$::jsonb)
on conflict (museum_id, language, id) do update set
  position = excluded.position, title = excluded.title, category = excluded.category,
  subtitle = excluded.subtitle, artist = excluded.artist, facts = excluded.facts,
  object_url = excluded.object_url, image = excluded.image, guide = excluded.guide;

insert into public.works (museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide)
select museum_id, language, id, position, title, category, subtitle, artist, facts, object_url, image, guide
from jsonb_populate_recordset(null::public.works, $seed$[{"museum_id":"henan","language":"zh","id":"henan-01","position":0,"title":"贾湖骨笛","category":"乐器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"新石器时代·裴李岗文化（约公元前7000—前5700年）"},{"label":"类别","value":"骨器·乐器（骨笛）"},{"label":"材质","value":"丹顶鹤尺骨"}],"object_url":null,"image":{"src":"/images/paintings/henan-01.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Early_Peiligang_Culture_Bone_Flute,_Wuyang.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"请先看这支骨笛身上那一排小孔。它是用丹顶鹤的尺骨做成的。鹤的骨头中间是空的，管壁却很薄，想在上面钻出整齐的孔并不容易，做的人显然很有耐心。笛身表面光滑，孔与孔之间的间距排得很匀，钻孔之前应当已经做过规划。笛身一侧排着七个音孔，手指按住或松开，就能改变音高，吹奏的人只用两只手，就能在几个音之间来回转换。这支笛子全长约二十三点六厘米，比一把普通的直尺短不了多少。它出土于河南舞阳的贾湖遗址，属于新石器时代的裴李岗文化，年代大致在公元前七千年前后。贾湖遗址出土的骨笛数量不少，据报道已有四十多支，这在早期乐器里相当可观。先看它的做工，再想象它在村落边被吹响时的样子。","expansion":"它的声音一直是研究的重点。1999年，有研究团队对贾湖一支保存较好的骨笛做了测音分析，结论是它的七个音孔可以组成接近七声的音阶，这在中国乐器史上引起了很大关注。不过这个结论主要依据少数几支完好的骨笛，还要靠现代人对古代声音的推断，所以学界至今仍在讨论，不宜当作定论。\n\n这支笛子上还有一个细节值得留意。除了七个主音孔，它的旁边还附有小孔，据报道，这些小孔可以修正因管径不均匀而造成的音高偏差。换句话说，制作的人并不只是钻孔了事，而是在反复调校。\n\n这支骨笛出土时断成了三截，断口处还留有缝合用的小孔。古人把它修好、继续使用，说明在他们眼里，这支笛子值得花力气保存。至于它是在仪式中吹奏，还是用于日常，目前没有确切的记录，我们只能从保存下来的器物本身去推测。","long":"我们先从材料说起。这支骨笛用的是丹顶鹤的尺骨，也就是翅膀前臂上的那根长骨。鹤骨中空、质地坚硬，对做工的人来说是个挑战：孔钻得太深容易裂，位置稍有偏差，声音也跟着走样。能把它做得这么规整，本身就说明制作者有很高的技术。\n\n笛身一侧排着七个音孔，呈一条直线。手指按住或放开，管内振动的空气柱长度随之改变，音高也就跟着变化。根据相关测试，它是竖着吹奏的，这个原理与后世许多竹笛、箫的道理相通。除了七个主音孔，这支笛子旁边还有修正音准的小孔，说明当时的人已经懂得通过细节去校准声音。\n\n这支骨笛出土于河南舞阳的贾湖遗址。贾湖属于裴李岗文化，年代大致在公元前七千年前后。遗址里出土的骨笛有四十多支，形制有两孔、五孔、六孔，也有七孔、八孔，七孔的数量最多。据报道，河南博物院把这一支出土时断成三截的骨笛列为镇院之宝之一。断口上留着缝合的痕迹，古人显然修好了它，又继续使用。\n\n关于它的声音，研究一直很热闹。1999年，有研究团队对保存较好的一支骨笛做了测音，认为它的音孔能排出接近七声的音阶。这个发现很重要，但它主要依据少数完好的骨笛，还要依靠现代人对古代声音的推测，所以学界至今仍有不同看法。\n\n至于它原本用来做什么，我们并不完全清楚。有学者推测它可能用于仪式或礼仪场合，但遗址本身没有告诉我们吹奏的是什么曲调，也不知道是谁在吹。我们能确定的，主要是它的材料、工艺，以及被修补、被反复使用的痕迹。\n\n那么，它今天为什么值得一看？据报道，它被认为是中国迄今发现最早的吹奏乐器之一。它告诉我们，中原地区的早期农耕社会，已经能把坚硬的骨头加工成可以调音、可以演奏的器物。请先看它做得多么精细，再想象它在村边被吹响时的样子。"}},{"museum_id":"henan","language":"zh","id":"henan-02","position":1,"title":"妇好鸮尊","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"商代晚期（约公元前13—前11世纪）"},{"label":"类别","value":"青铜器·酒器（鸮形尊）"},{"label":"材质","value":"青铜"},{"label":"尺寸","value":"通高46.3厘米；重16千克"}],"object_url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512159573394606792","image":{"src":"/images/paintings/henan-02.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Bronze_owl-shaped_Zun_with_inscriptions_of_Fu_Hao,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"请先看这只鸟的头部。两只小耳朵立在高高的冠上，圆眼睁着，宽喙朝前，双翅紧紧收在身侧。这是一只猫头鹰，也就是“鸮”，用青铜铸成，属于商代晚期，距今三千多年。它是一件酒器，名叫“尊”。再看它怎样站稳。粗壮的双足加上下垂的宽尾，在地面上正好形成三个支点，尾巴不只是装饰，它也是承托身体的一条“腿”。最后俯身看器口下方的内壁，那里铸着两个字：妇好。这两个字说明器物的主人是妇好，她是商王武丁的妻子，也是率兵征战、主持祭祀的重要人物。1976年，她的墓葬在河南安阳殷墟被发掘，这只鸮尊就出土于那里。墓中出土的青铜器数量很多，这件鸮尊是其中格外醒目的一件。一件三千多年前的酒器，让人一眼认出它是只猫头鹰，这本身就很不寻常。","expansion":"鸮尊的表面几乎处处有纹饰，可轮廓依然清楚。器身以雷纹为底，像一层细密的回环纹理。喙部和胸前有蝉纹，颈部两侧各有一条双头怪夔，两翅前端各盘着一条蛇，颈后和器盖上饰有饕餮纹。这些纹饰挤在一起，却没有抢走鸟形的存在感，这也是它耐看的原因之一。器盖上还立着一只小鸟，后面伏着一条龙。馆方的介绍认为，商人把鸮看作神禽，而不是恶鸟。不过猫头鹰在后世的名声变化很大，有学者指出，把它视为不祥之兆的说法主要形成于周代。同一种动物，在不同时代可以有完全不同的含义，所以不能想当然地去解读它。另有一件同类的鸮尊收藏在中国国家博物馆，两件器物近年在河南首次同框展出，让人有机会对照它们的细节。","long":"先看轮廓。这是一只猫头鹰，用青铜铸成，距今三千多年。它靠两条粗壮的腿和一条下垂的宽尾站在地上，三点着地，显得稳当。再看头部，高冠之下是两只小耳朵、一双圆眼和宽宽的喙，双翅紧紧收在身侧。整只鸟既静止，又像随时会警觉转头，这种静与警觉之间的张力，让它显得很有生气。\n\n它其实是一件酒器，名叫“尊”。这类器物多用于祭祀和宴飨的场合，而鸟的身体本身就是容器。你注意头部后方那里，开着一个四分之一圆形的口，配有盖子。盖子上还立着一只小鸟，后面伏着一条龙。动物造型和器物的功能，在这里合为一体。\n\n器身表面非常密。几乎整个器身都以雷纹为底，像一层细细的回环纹理。在这层底纹之上，喙部和胸前有蝉纹，颈部两侧各有一条双头怪夔，翅膀前端各盘着一条蛇，颈后和器盖上又有饕餮纹。这些纹饰看似繁复，但鸟的轮廓依然清楚，眼睛一扫便能认出它。\n\n再俯身看器口下方的内壁，那里铸着两个字：妇好。这说明器物的主人是妇好，她是商王武丁的妻子，也是一位率兵征战、主持祭祀的重要人物。1976年，她的墓葬在河南安阳殷墟被发掘，墓中随葬的青铜器有四百多件，这只鸮尊就是其中之一。随葬器物往往与墓主的身份和地位有关，这也是理解它的一个线索。\n\n为什么做成猫头鹰？馆方的介绍认为，商人把鸮视为神禽，而不是恶鸟。不过猫头鹰在后世的名声变化很大，有学者指出，把它看作不祥之兆的说法主要形成于周代。同一种动物，在不同时代可以有完全不同的含义，所以我们不能想当然地去解读它。\n\n这件鸮尊还有一个“伴侣”。另一件同类器物收藏在中国国家博物馆，两件器物近年在河南首次同框展出。站在它面前的你，也许会问同一个问题：三千多年前的工匠，是怎样让一只铜鸟看起来既安静又警觉的？"}},{"museum_id":"henan","language":"zh","id":"henan-03","position":2,"title":"莲鹤方壶","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"春秋时期（公元前770—前476年）"},{"label":"类别","value":"青铜器·方壶"},{"label":"材质","value":"青铜"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zpjc/qtq/articlea5e2192480c947a0846136edc2adeb21.html","image":{"src":"/images/paintings/henan-03.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Rectangular_Pots_with_Lotus_Petal_Cover_and_Crane_Decoration_01.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"先看顶上。盖子中央立着一只仙鹤，双翅展开，昂首而立，喙微微张着，像是引颈欲鸣。它脚下是两层莲瓣，共十组，每片花瓣上都有镂空的纹饰，远看像一圈精致的花边。顺着目光往下，壶身的截面是方的，口呈长方形，颈部细长，肩部斜收，腹部鼓起，再缓缓收向底座。颈部四面有龙形的耳，腹部四角各附一条有翼的小龙，龙身沿着器壁攀爬。圈足下还有托住器身的神兽。盖与身相合，通高117厘米，站在它面前，就能感到它的分量。这是一件“壶”，古人用来盛酒或别的液体。它铸于春秋时期，大约公元前6世纪，那时周王室的权威已经衰落。造型与纹饰都很繁复，需要细细看才能发现其中的变化。不妨顺着线条的走向看一圈，你会发现许多线条最终都汇向那只仙鹤。","expansion":"这件器物是在地下被找到的。1923年8月，河南新郑李家楼一带挖出了一座规模很大的墓，人们习惯称它为郑公大墓。郑是春秋时期的一个小国，但墓主究竟是哪一位郑国国君，至今没有定论，学者提出过几种推测，仍各执一词。同时出土的是一对，如今一件在这里，另一件在北京故宫博物院。这一对器物后来分藏两地，所以我们今天看到的，只是当年的一半。\n\n这里还有一个值得留意的地方。河南博物院的藏品说明认为，这件壶很可能是郑国国君的陈设品，而不一定是日常倒酒用的容器。这属于推测，却很有启发：器物的形状告诉我们它能做什么，它的规模和装饰则往往说明主人想让别人看到什么。莲花和仙鹤常被理解为纯洁与长寿的象征，不过这更多是后人的解读，并没有可靠的文献说明工匠当初的本意。郭沫若为它定名“莲鹤方壶”，这个名字抓住了最醒目的两样东西。","long":"我们先从顶上开始。盖子中央立着一只仙鹤，双翅展开，昂首而立，喙微微张着，像是引颈欲鸣。仙鹤下面是两层莲瓣，共十组，每片花瓣上都有镂空的纹饰，整个盖子因此不像一块实心的铜，倒更像一圈精致的花边。顺着盖子往下看，壶身的截面是方的，口呈长方形，颈部细长，肩部斜收，腹部向外鼓起，再缓缓收向底座。\n\n壶上的龙无处不在。颈部四面都有龙形的耳，其中两个位于正侧面，构成一对可以提拿的双耳。腹部四角各附一条有翼的小龙，身子沿着器壁爬上来，姿态很活泼。器身上还布满了浅浮雕和细线刻出的花纹，龙、凤等纹饰交织在一起。圈足下面托着器身的，据不同资料描述，有的说是两条龙，有的说是两只卷尾的兽，这里不妨把它们看作撑起整件器物的神兽。\n\n这件东西很重。河南博物院的藏品记录给出的重量约为六十四公斤，通高一百一十七厘米。它不是一件可以随手提起来的酒器，更像是摆在厅堂里、需要郑重对待的重器。\n\n它是一件“壶”，古人用来盛酒或别的液体。但博物馆的说明提醒我们，这么大、这么精细的壶，很可能主要是郑国国君的陈设品，用来显示身份与财富，未必天天拿来倒酒。这一点属于推测，却很有启发：形状说明器物能做什么，规模和装饰则往往说明它想让人看到什么。\n\n它铸于春秋时期，大约公元前6世纪。那时周王室的权威已经衰落，各诸侯国纷纷崛起，郑国正是其中之一。博物馆的说明认为，这件作品是春秋时期多范合铸工艺的代表作。也就是说，工匠要用多块陶范拼合起来，一次浇铸出复杂的整体，把龙、莲瓣和仙鹤都做进同一件器物里，难度不小。\n\n它出土于1923年，地点是河南新郑李家楼一带的一座大墓，考古界习惯称其为郑公大墓。墓主究竟是哪一位郑国国君，至今没有定论。这一对器物后来分藏两地，一件在这里，另一件在北京故宫博物院。郭沫若为它定名“莲鹤方壶”，这个名字抓住了最醒目的两样东西。\n\n莲花与仙鹤常被理解为纯洁和长寿的象征，这种解读很有道理，但它更多是后人的阅读，并不是有文献记载的制作本意。所以，不妨把这件器物当作一个问题来看：工匠把线条一层层引向那只仙鹤，他究竟想让人注意什么？你站在它面前，慢慢顺着线条走一圈，也许会得到自己的答案。"}},{"museum_id":"henan","language":"zh","id":"henan-04","position":3,"title":"武则天金简","category":"玉器·金器·兵器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"唐代·武周时期（公元700年）"},{"label":"类别","value":"金器·投龙简（祭祀铭文）"},{"label":"材质","value":"金合金（据馆方检测，约九成金、一成银）"}],"object_url":null,"image":{"src":"/images/paintings/henan-04.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Wu_Zetian_Gold_Strip,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"先看它的材质。这条窄窄的金片，长约三十六厘米，表面刻着六十多个字，却从来不是给人欣赏的摆件。它是一份呈给神明的文书。大约公元700年，武则天晚年，她派了一位道士使臣，把这枚金简投入河南嵩山，交给天上的神灵。文字开头写着「大周国主武曌」，「曌」正是武则天自己创造的字。早年学者根据「除武曌罪名」几个字，把它叫作除罪金简；如今多数研究者倾向于理解为祈福消灾。站近些看，字不是印出来的，而是用工具一笔一笔刻在金片上的。这类投送的简，先前多用玉、银或青铜制作，据现有报道，这是目前已知的首件金质实物。它于1982年在嵩山的岩缝中被发现，如今是河南博物院的镇馆之宝。读的时候不妨慢一点，你读到的是一位统治者向神明发出的恳求。","expansion":"再看它是怎么做出来的。金子先被锤打成约一毫米厚的薄片，然后用工具在上面刻字。字体是双钩楷书，也就是先用两道平行的线勾出笔画的轮廓，这原本是书法里的写法，远看又有点像墨写的。刻完之后，整面再打磨，让表面更加光亮。金子也不是纯金。河南博物院在2008年做过无损检测，结果约为九成金、一成银。不过也有报道给出了更高的含金量，具体成分如今仍有出入。简这种器物，古人本用窄长的板片书写，这件金简沿用了这种形式，只是把材料换成了金。它能流传下来，几乎靠运气。1982年5月，嵩山峻极峰上一位年轻农民起初以为这是包点心的金箔，擦去泥土，才看清上面的字。有文物商人出价十万元，他没有卖，而是把它交给了国家。","long":"想象一下，你面前是一片细长的金片，单手就能托起。它看上去像一件装饰品，其实从来不是为了陈列。它是一份呈给神明的文书，而写下这份文书的，是一位女皇。\n\n武则天是中国历史上唯一以皇帝身份统治的女性。她建立了武周王朝，使唐朝中断了大约十五年。据铭文记载，公元700年七月七日，她派了一位道士使臣胡超，来到嵩山。嵩山是五岳中的中岳，在道教传统中地位很高。胡超的任务，是把这片金简投进山中，请天官、地官、水官和九府的神明，赦免武曌的罪名。\n\n铭文不长，只有六十三个字，却有几处很耐人寻味。其中有五个字是武则天自创的，最有名的就是「曌」，她用它来写自己的名字。也就是说，这些文字很可能经过她本人的斟酌。这些字在她退位之后便不再通行，所以这件金简，也成了一件与她直接相关、保存至今的实物，格外珍贵。\n\n这里就要说到学界的争论了。早期研究者按字面把它叫作「除罪金简」，把「罪」理解为道德上的过失。但越来越多的研究者提出，「罪」在这里也可能指疾病或苦难。史书记载，那年五月武则天患病，服用了胡超配制的丹药，病情只恢复了一部分。于是，有学者认为这更像是一份祈福消灾的文书，希望神明保佑健康与平安。有学者还注意到，胡超只是一位道士，并非朝中重臣，这也与一次宗教祈祷的性质相符。不过，这仍是一种推断，铭文本身并没有明说。\n\n所以，这片金子究竟是认错，还是祈求，两种读法都有依据。它告诉我们的，是一位仍然大权在握的统治者，在晚年选择向山川与神明求助，并且用金子来写这份请求，本身就说明了它的分量。\n\n这片金子是1982年5月在嵩山峻极峰的一处岩缝里被发现的。那位农民起初以为这是包点心的金箔，后来把它交给了国家，如今是河南博物院的镇馆之宝。无论你更相信哪种读法，它都保留了一种正史里很少见的声音：一位君主，用她自己斟酌过的字句，向上天恳求原谅或庇佑。"}},{"museum_id":"henan","language":"zh","id":"henan-05","position":4,"title":"云纹铜禁","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"春秋晚期（铸造年代不晚于公元前552年）"},{"label":"类别","value":"青铜器·禁（承酒器）"},{"label":"材质","value":"青铜"},{"label":"尺寸","value":"通高28.8厘米；身长103厘米；宽46厘米；重95.5千克"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/mzyp/article9ff964490b3b4f02be4f5e622a87614f.html","image":{"src":"/images/paintings/henan-05.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Spring_%26_Autumn_Bronze_Jin_-_10336384816.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"请先抬起头，看看这件器物的顶部。它乍看像一个实心的托盘，走近才发现，那是一片由云纹组成的镂空网格，透过它能看到下面中空的框架。这件青铜器叫“禁”，是用来承放酒器的座子。它是春秋晚期的楚国器物，铸造年代不晚于公元前552年，出土于河南淅川的下寺楚墓。框架四周攀附着十二条龙形附兽，底下又有十二个龙形座兽托着整个器身。器壁薄不足五厘米，内部有五层铜梗结构，外层的云纹则是透雕而成。它通高不到29厘米，却重达约95公斤。这样又沉又精细的青铜器，并不多见。不妨先从顶部的网格看起，再慢慢往下，看看那些龙形附兽和座兽是怎样与器身连在一起的。附兽与器身是以卯榫方式结合的，并非简单地贴附上去。","expansion":"这件器物更让人好奇的，是它的铸造方法。河南博物院的记录把它列为我国最早用失蜡法铸造的青铜器之一。这种方法大致是：先用蜡做出模型，外面包上泥料，再加热让蜡熔化流出，留下的空腔正好用来灌注铜液。如果禁真是失蜡法铸造，那么这件器物就会改写人们对这项技术出现时间的认识。不过，学界对此并不一致。有研究者认为，禁体是由二十五块蜡模拼接后一次浇注而成，器身上没有明显的范缝。也有学者提出疑问，认为先秦时期的失蜡法缺少逐步发展的证据，这件禁是否真用此法，至今仍有争议。无论结论如何，它都说明，两千五百多年前的工匠已经能够控制大面积、镂空复杂的铜液流动，这本身就足够令人惊叹。","long":"请抬起头，看看这件青铜器的顶部。它看上去像一个实心的托盘，其实是一片用云纹组成的网格，镂空得可以让你直接透过去，看到下面的框架。整件器物通高不到29厘米，重量却接近95公斤，整个器身由底下的十二个座兽托起。器壁不到五厘米厚，内部另有五层铜梗结构，外层云纹则是透雕而成。它既要承托沉重的器身，外表又要做得轻巧通透，这种反差正是它的看点。\n\n它叫“禁”，是用来承放酒器的青铜座。“禁”字一般读作“禁止”，历来有一种解释，认为它与周代的禁酒观念有关。不过这只是传统说法，器物本身并不能证明。器物本身能说明的，是制作者对待酒器的讲究。器身四周攀附着十二条龙形附兽，底部十二个龙形座兽撑起器身，附兽则以卯榫方式与器身相接。有学者推测，这些龙形造型与楚人崇尚龙的风俗有关，这一点同样只是推测。\n\n这件禁出自楚国，属于春秋晚期，铸造年代不晚于公元前552年。它出土于河南南阳淅川的下寺春秋楚墓。1979年3月至4月，下寺墓地经过科学发掘，墓葬曾遭盗掘，仍出土了八十余件大型青铜礼器。据考证，墓主为楚庄王之子王子午。这件禁出土时已经破碎成数百块，修复人员历时四年才把它重新拼合起来。\n\n最值得玩味的，是它的铸造方法。河南博物院的记录称，它是我国最早用失蜡法铸造的青铜器之一。失蜡法的大致过程是：先用蜡做出模型，外面包上泥料，加热让蜡熔化流出，留下的空腔用来灌注铜液。有研究者认为，禁体由二十五块蜡模拼接后一次浇注而成，器身上没有明显的范缝。但也有学者怀疑，先秦时期是否已经掌握这种技术，因为缺少逐步发展的证据。这个问题至今没有定论。无论最终如何，这件器物都说明，两千五百多年前的工匠已经能够驾驭大面积、镂空复杂的铜液流动。"}},{"museum_id":"henan","language":"zh","id":"henan-06","position":5,"title":"杜岭方鼎","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"商代早期（约公元前16—前15世纪）"},{"label":"类别","value":"青铜器·礼器（方鼎）"},{"label":"材质","value":"青铜"},{"label":"尺寸","value":"通高87厘米；重约64.25千克"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zyzb/articlecc3a53c2a97149d4bf62fb583ef0dc9d.html","image":{"src":"/images/paintings/henan-06.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20250527_Nipple-nailed_square_ding_with_beast_face_patterns_in_the_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Yumeto"},"guide":{"short":"请先绕着这件青铜器慢慢走一圈，从四个角看起。它的器身是方的，四壁笔直，口沿平整，两只耳朵立在口沿上，下面由四条中空的圆柱形足托起。方形器身加上笔直的四壁，使它的轮廓格外硬朗，两只耳朵不大，却稳稳立在口沿上。这种器物叫鼎，是商代在祭祀时盛放食物的礼器。这件通高约87厘米，重约64公斤，即使空着也很沉。它铸造于商代早期，距今三千多年。请把目光移到腹部上方，那里有一张瞪着大眼的兽面，学名叫饕餮纹。器身两侧和下半部又布满小小的圆突，叫乳钉纹。它们各自的含义，学界至今仍有争论，但排列得如此整齐，说明纹饰事先经过精心规划。你眼前的这件，是1974年在郑州出土的一对方鼎中较小的一件。","expansion":"这件鼎有一个特别之处：它不是单独出土的。1974年9月，郑州张寨南街一带的工人在挖防空地道时，于地下约六米处发现了两件方鼎，它们并排嵌在地道右壁上。较大的那件内放着一件铜鬲，说明器物是成组放置的，而不是随手丢下的。两件鼎中，较大的一件高约一米，如今收藏在中国国家博物馆；这件较小的则藏于河南博物院。埋藏地点距离郑州商城西城墙外约300米，郑州商城被认为是商代早期的重要城址，因此这批青铜器可以帮助研究者了解城址周边的情况。那么，为什么要把这么重的器物埋入地下？考古学家杨育彬先生认为，两件鼎埋藏得整齐规范，可能与商王的祭祀有关。这是一种推测，目前并没有定论。可以确定的，是铸造它们所耗费的人力与金属。不论埋藏的原因如何，这两件鼎都说明，当时的统治者有能力组织起大规模的生产。","long":"请先从四个角看起。这件青铜器不像碗，更像一只方箱子。器身是方的，四壁笔直上升到平整的口沿，口沿上立着两只耳，下面由四条中空的圆柱形足托着。这种器物叫“鼎”，是商代在祭祀时用来盛放食物的礼器，地位很高。\n\n这件方鼎通高约87厘米，口部每边约61厘米，连同器身约重64公斤。光是抬起它，就需要不少人手。商代青铜器多用陶范法铸造，先制作内外范，再把它们拼合起来，浇入铜液。这样大的器物需要大量金属，还需要许多熟练工匠密切配合，任何一步出错，整件器物都可能报废。\n\n再看纹饰。腹部上方有一张瞪着大眼的兽面，学名叫饕餮纹，这种图案在商代青铜器上非常常见。器身两侧和下半部，则分布着许多小小的圆突，叫乳钉纹，排列整齐有序，把大片器壁划分开来。饕餮纹的含义，学界至今仍有争议，乳钉纹的作用也并不完全清楚。可以确定的是，纹饰经过了仔细规划，所以值得你慢慢绕着它走一圈。\n\n这件鼎的发现过程同样引人注目。1974年9月，郑州张寨南街一带的工人在挖防空地道时，于地下约六米处发现了它。地点位于郑州商城西城墙外约300米处，对研究这座早期商城的布局是重要的参照。两件方鼎并排嵌在地道的右壁上，较大的那件内部还放着一件铜鬲。发现者的说法，各种资料并不一致。\n\n这批器物为何被埋在这里，是个更难回答的问题。考古学家杨育彬先生认为，两件鼎埋藏得整齐规范，可能与商王的祭祀活动有关。这是一种推测，并未得到证实。另一个问题同样悬而未决：郑州是否就是某位商王的都城，学界看法也不统一。因此，这件器物既是实物，也是这场讨论中的证据。\n\n无论它的确切用途如何，这件方鼎都说明，商代青铜铸造已达到相当高的水平。它的线条简洁，棱角分明，又不失厚重感。站在它面前，不妨再仔细看看那些转角和纹饰，它们正是当年工匠功夫的体现。"}},{"museum_id":"henan","language":"zh","id":"henan-07","position":6,"title":"玉柄铁剑","category":"玉器·金器·兵器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"西周晚期（约公元前8世纪）"},{"label":"类别","value":"兵器（玉器、铁器）"},{"label":"材质","value":"铁剑身；青铜柄芯嵌绿松石；和田青玉剑柄"},{"label":"尺寸","value":"通长34.2厘米；柄长12.2厘米"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/bwzl/jxysyhjsqjytzgygbz/jyhy/article2ff8d5d4e3a44448b3233e8c57835a1d.html","image":null,"guide":{"short":"先别急着看剑刃，把目光落到剑柄上。这截柄看上去像一整块青玉，其实是拼合的。两段中空的和田青玉套在一根青铜芯子上，玉件两侧的小孔里穿着铜销钉，把玉和铜牢牢固定在一起。柄首中部还嵌着绿松石片，一点蓝绿色，在温润的青玉上格外显眼，铜芯表面的绿松石条也与之遥相呼应。再看剑身，它是铁的。在西周，铁比青铜稀少得多，能把铁身和青铜芯锻接在一起，这本身就是一门手艺。这把剑出自三门峡虢国墓地的二零零一号墓，一九九零年发掘。墓主是一位虢国的贵族，这样的人家里，青铜器才是常见的体面，一把铁身的剑，显然不会随处可见。玉、铜、铁三种材料凑在一把剑上，你觉得它更像用来打仗的，还是更像用来显示身份的？","expansion":"剑身的故事更有争议。一些通俗文章说，这把剑的铁是人工冶炼的，甚至说它把中国冶铁的历史提前了两百年。这些说法流传很广，但我们能查到的正式材料里，并没有直接对这把剑下这样的结论。北京大学的一篇论文讨论了虢国墓地，认为墓地里带铁刃的青铜器，是中原地区较早使用人工冶铁的实物例证之一。这句话指的是整个墓地，并不单独针对这一把剑。另外，有学者推测，剑身、玉柄和青铜芯是分开做好，再用漆粘合起来的，但这个推测还没有经过科学检测。所以站在这里看它，您看到的既是一份证据，也是一个尚未有答案的问题。要说的话，虢国墓地里带铁刃的青铜器不止这一件，把它们放在一起看，比单独研究一把剑更能说明问题。","long":"很多人进门第一眼被玉吸引，这没错。这截剑柄用的是和田青玉，颜色偏青绿，温润而不透亮。它并不是一块整玉挖出来的，而是由两段玉件套接而成：柄茎是圆柱形，中间挖空，正好套住一根青铜芯子；柄首中部嵌着几条绿松石，两侧有透穿的小圆孔，铜销钉从孔里穿过，把铜芯和玉首固定住。铜芯表面也嵌着条状的绿松石，一小片一小片蓝绿色。工匠没有把接口藏起来，而是用铜销钉明明白白地锁住它，这种做法很实在。\n\n真正让人意外的是剑身。它是铁的，铁身与青铜芯在两面锻接在一起，说明三种材料不是简单地装在一起。铜芯的前段被做成条状，便于和剑脊上的铁连接。在西周时期，青铜是礼器和兵器的主角，铁则稀少而珍贵。所以，一把铁身的剑出现在贵族墓里，本身就值得多看一眼。\n\n这把剑出自河南三门峡虢国墓地的二零零一号墓，发掘于一九九零年。虢是西周时期的诸侯国，这座墓一般被认为是虢季墓，不过要说明的是，墓地的年代跨度比较大，有研究把它定在西周晚期到春秋早期，所以这座墓的确切年代，学界仍在讨论。博物馆的正式藏品记录写的是西周，这一点也值得留意。\n\n至于剑身的铁是怎样冶炼出来的，目前比较有把握的说法是：这一墓地的带铁刃青铜器，是中原地区较早使用人工冶铁的实物例证之一。民间流传的一些说法，比如说它把冶铁史提前了两百年，或者说它的铁是某种特定的炼钢工艺做成的，在我们能查到的材料中，还没有找到足以支持的科学报告。有学者还提出，剑的几个部分可能是分开做好，再用漆粘合的，但这个想法同样没有经过检测。\n\n那么，一把同时用玉、铜、铁做成的剑，为什么要陪葬进贵族的墓里？它可能显示了拥有者的身份，也可能只是贵族珍爱的稀罕之物。这些都是推测，文献和实物都没有给出明确的答案。站在它面前，不妨想一想：这三种材料里，哪一样才是墓主人最珍视的？"}},{"museum_id":"henan","language":"zh","id":"henan-08","position":7,"title":"四神云气图壁画","category":"壁画","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"西汉早期（约公元前2世纪）"},{"label":"类别","value":"墓葬壁画"},{"label":"材质","value":"颜料绘于墙面"}],"object_url":null,"image":{"src":"/images/paintings/henan-08.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Four_Deities_in_Clouds,_Western_Han_Tomb_Mural_Painting.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"请抬头看。这幅画原本不是挂在墙上的，而是画在西汉一座王侯墓室的顶部。站在墓里仰望，眼前就是一片彩色的天空。画面中央，一条飞龙占据了最醒目的位置，长长的龙须随风般飘动。上方是朱雀，下方是白虎，四周翻卷的云气把它们连成一片，报道形容这些云气勾勒得神秘而灵动，仿佛把人带进了一个天界。这几种神兽，在汉代常被看作分守四方的神灵，画名“四神云气图”便由此而来。它属于西汉前期，大约是公元前二世纪。据媒体报道，它是中国目前所见唯一一处西汉前期诸侯王级的巨幅彩色壁画。如今原作已经离开墓葬，搬到河南博物院展出，墓中留下的只是复制品，去博物院看原作，能看清更细的笔触。下次来，不妨先站在它下面，抬头看一会儿。","expansion":"这幅壁画不是为住宅或寺庙而画的，它属于一座诸侯王墓。这座墓位于河南永城的芒砀山，是在坚硬的山岩中开凿出来的。报道中多将墓主指认为西汉梁国的梁共王刘买，不过其他说法并不完全一致，所以墓主的身份仍需谨慎看待。这也意味着，墓顶的图像要放在墓葬整体结构中去理解。画中的四方神灵里，有一位最容易引起讨论。通常认为它代表北方的玄武，也就是龟蛇合体的神兽，可是画中的形象与常见的玄武并不完全吻合，有报道干脆称它为“怪兽”。这说明，汉代的神兽图像未必都按后世的固定样子出现。这座墓在1991年入选“全国十大考古新发现”，报道中这一荣誉授予的是整座墓葬，而不是壁画本身。你看到的既是一幅神话图像，也是一个至今仍有争议的图像谜题。","long":"先从天花板说起。这幅画在墓里的位置，决定了观看的方式：你不是站在墙前欣赏，而是要仰起头，在墓室顶部的下方，看一片彩色的天。画面中央是一条飞龙，长长的龙须飘动，占据了最醒目的位置。龙的上方是朱雀，下方是白虎。剩下的那一位，通常被认为是北方的玄武，但画中的形象与常见的玄武并不完全吻合，有报道干脆称之为“怪兽”。这提醒我们，汉代的神兽图像未必总是按后世的固定样子出现。灵芝、云气纹等纹样穿插其间，把这些神灵连在一起，让整幅画读起来像一片天空。报道形容这些云气勾勒得神秘而灵动，站在下面仰望时，这种感觉尤其明显。\n\n接下来说它的所在。这座墓位于河南永城的芒砀山，是在坚硬的山岩中开凿出来的。它1986年被发现，1991年入选“全国十大考古新发现”，这一荣誉授予的是整座墓葬，而不是壁画本身。报道中多将墓主指认为西汉梁国的梁共王刘买，不过其他说法并不完全一致，墓主是谁至今仍需谨慎看待。这一点很要紧，因为墓主的身份，关系到我们如何理解这些神灵出现在墓顶的意义。墓葬与画作的年代属于西汉前期，大约在公元前二世纪。据一份资料记载，画幅高约327厘米、宽约514厘米，但也有资料给出了不同的尺寸，这一数字还有待核实。\n\n它的命运同样值得一提。原作已经离开墓葬，如今在河南博物院展出，墓中所见的则是一幅巨大的复制品。把一幅墓顶壁画从地下请进博物馆，它离开了原来的环境，却让人们可以近距离观察它的线条与色彩。据媒体报道，它是中国目前所见唯一一处西汉前期诸侯王级的巨幅彩色壁画。这是报道中的判断，我们只能依据目前可见的资料来理解它。对于研究西汉早期墓葬绘画而言，它是一份难得的实物材料。站在它面前，你看到的，是一片曾经封存在地下的天空。"}},{"museum_id":"henan","language":"zh","id":"henan-09","position":8,"title":"汝窑天蓝釉刻花鹅颈瓶","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"北宋（960—1127年）"},{"label":"类别","value":"瓷器·汝窑"},{"label":"材质","value":"瓷胎，天蓝釉，香灰色胎"},{"label":"尺寸","value":"高19.5厘米；口径5.6厘米；底径8.2厘米"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/dzjp/zpjc/cq/article23f85aa418494272a448ad9fceced19e.html","image":{"src":"/images/paintings/henan-09.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:汝窑天蓝釉刻花鹅颈瓷瓶.png","license":"CC BY-SA 4.0","author":"陳寅恪"},"guide":{"short":"先看颜色。这只瓶通体覆着一层天蓝釉，釉面匀净光润，像雨后初晴的天空。它是北宋汝窑的作品，通高十九点五厘米，身形修长：口部微微外撇，颈细长，腹部圆润，下面托着一个小圈足。轮廓是一道柔和的S形曲线，不张扬，却很耐看。仔细看颈部和腹部，那里刻着折枝莲花，花纹并不浮在釉面上，而是隐隐透在蓝色之下。光线一转，它便时隐时现。颈的修长与腹的圆润之间互相呼应，比例匀称，是这件器物最耐看的地方。汝窑以天蓝釉闻名，存世的天蓝釉汝瓷数量有限，所以眼前这件格外珍贵。它1987年出土于河南宝丰清凉寺村，那里正是汝窑窑场所在地。一件瓷器能保存到今天已经很不容易，不妨慢慢看，它会把细节一点点交给你。","expansion":"请把瓶子翻过来看看，底部藏着烧造的线索。圈足没有施釉，露出灰褐色的胎体，上面粘着细小的砂粒。这些砂粒说明瓶子在窑中是垫着支具烧的，并非直接落在窑床上。原因很实际：釉在高温下会熔化、与接触的东西粘连，所以底部通常要留出来。再看釉面，细密的开片纹均匀铺开，在光下呈现一道道发丝般的裂纹。这是釉层与胎体冷却时收缩程度不同形成的，也是汝瓷釉面的一个显著特征。那么，它究竟烧于何时？学界对汝窑的烧造年代说法不一，有的估计窑场只持续了二十年左右，有的估计要长得多。许多研究把它与宋徽宗时期联系起来，但这一联系仍在讨论之中。所以，欣赏那片蓝色的同时，也不妨留一点疑问。","long":"先从颜色说起，这是大多数人最先注意到的地方。这只瓶上的釉是一种清淡的天蓝色，釉面匀净，光泽温润。它属于汝窑，是北宋时期烧制的瓷器，窑场遗址位于今天的河南宝丰县清凉寺村。汝窑的名称一般认为与古代的汝州有关，它在北宋后期与宫廷的关系一向被认为十分密切，因此它的烧造要求和审美标准都比一般民窑瓷器更高。\n\n这件瓶子的轮廓也很讲究。口部微微外撇，颈部细长，腹部圆润，底下承着一个小圈足，整体是一道松弛的S形曲线。它高十九点五厘米，不算大，却很有分量感。拿在手边，会觉得器形像是为了被仔细端详而设计的。\n\n真正让它与众不同的，是颈部和腹部那两组刻花。两组都是折枝莲花，刻在胎体上，再施釉覆盖。花纹并不浮在表面，而是隐隐透在釉色之下，像藏在水底。光线斜照时，莲花便慢慢显现；换个角度，又隐没于蓝色之中。这种釉下隐现的效果，需要胎体和釉层的配合恰到好处，是理解这件作品工艺水准的关键。\n\n翻过来看底部，故事就变得具体了。圈足没有施釉，露出灰褐色的胎体，上面粘着细小的砂粒。这些砂粒说明瓶子烧制时是垫着支具放在窑里的，而不是直接落在窑床上。釉在高温下会熔化、粘住接触的东西，所以底部通常要留出来，这是窑工们的常识。\n\n这只瓶的出土经历也值得一提。1987年，它在清凉寺村被发掘出土，就在窑址所在地。也就是说，它是在烧造的地方被找到的，而不是出自墓葬或宫殿。但我们并不知道它原本用于何处、由谁使用、摆放在什么地方。博物馆的记录没有说明它的原始用途。有学者把鹅颈瓶归入陈设器一类，这只是一种分类意见，不宜当作定论。\n\n汝窑的烧造时间，学界至今仍有争论。有的估计它只生产了二十年左右，有的估计要长得多，年代范围并不统一。许多研究把它与北宋宋徽宗时期联系起来，但这种联系同样没有定论。因此，当你看着这抹蓝色时，不妨一边欣赏，一边意识到，它的身世仍有许多未解之处。"}},{"museum_id":"henan","language":"zh","id":"henan-10","position":9,"title":"彩陶双连壶","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"新石器时代·仰韶文化（约公元前3500—前3000年）"},{"label":"类别","value":"彩陶·饮酒器"},{"label":"材质","value":"泥质红陶，红衣黑彩"},{"label":"尺寸","value":"高20.1厘米；底径5厘米"}],"object_url":"https://www.chnmus.net/sitesources/hnsbwy/page_pc/bwzl/yyhxzzjd/cpsx/article02dad096e98349b19ed9feaa402f6667.html","image":{"src":"/images/paintings/henan-10.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Yangshao_Culture_Painted_Pottery_Twin_Flasks.jpg","license":"CC0","author":"Gary Todd"},"guide":{"short":"请您先看这件器物的外形。乍一看像一只陶壶，细看才发现，它其实是两只壶并排立着，腹部连在一起，中间开一个椭圆形的孔，让两边相通。这是仰韶文化的彩陶双连壶，1972年出土于郑州大河村遗址。两只壶的形状几乎一模一样，表面是细腻的红陶，外面涂一层红色陶衣，再用黑色颜料画出粗粗的平行横线，线条之间点缀着一竖一斜的短笔，排列整齐，疏密有致，在红色的陶面上显得既古朴又利落。河南博物院的展品说明认为，它是一件饮酒器，多用于重要的礼仪场合，使用时两个人各执一壶，同时饮用。高约二十厘米，小到双手就能捧起，这件器物的用途和造型正好彼此呼应。它的造型本身就透露出一个意思：喝酒这件事，最好有人一起。","expansion":"再仔细看看黑色的花纹。两只壶上的短线并不完全相同，一边是竖着画的，另一边是斜着画的。这种差别的含义目前并不清楚，不能简单理解。博物馆的说明提到，这件器物可能用于部落结盟时共饮盟誓，这是一种推测，器物上没有文字可以直接证明。也有人把它和后世的交杯酒联系起来，这种联想很有吸引力，但目前缺少直接证据，说明中也明确指出需要进一步考证。这一点值得留意，博物馆并没有把自己的判断说得太满。也就是说，我们今天能确定的，是一套有据可依的工艺，而围绕它的用途解释，仍在讨论之中。真正能确定的，是制作者的手艺：要做出两个形状相近的器身，把它们连接在一起并烧制成型，再在弧形的表面上均匀地绘出图案，对当时的陶工来说，并不是一件轻松的事。","long":"我们先从形状说起。眼前这件器物，看上去像一只陶壶，其实是两只壶。两个器身并排立在一起，腹部相连，中间开一个椭圆形的孔，让两边相通。两只壶的大小和形状几乎一样，高约二十厘米，底部直径五厘米，小到双手就能捧住。\n\n它属于仰韶文化。仰韶文化是新石器时代的重要文化，主要分布在黄河中游一带，彩陶是它最有代表性的器物。红色陶衣让表面颜色均匀，黑色花纹在上面显得格外清楚。这件双连壶用泥质红陶制成，胎土细腻，表面先涂一层红色的陶衣，再用黑色颜料画出花纹。花纹以粗粗的平行横线为主，线条之间点缀着短线，有的一竖，有的一斜。要让两只壶的纹样在弧形的器身上同时清晰、同时协调，对当时的陶工来说，需要相当的经验与控制力。\n\n它1972年出土于郑州的大河村遗址。大河村是一处延续时间很长的古代聚落，不同时期的文化层在这里层层叠压，留下了丰厚的遗存。\n\n那么，它是做什么用的呢？河南博物院的展品说明认为，这是一件饮酒器，多用于重要的礼仪场合。使用时，两个人各拿一只壶，同时饮用。中间那个椭圆形的孔把两个器身连通起来，所以它的造型本身就带有共享的意味。对照这一点来看，它的设计并不只是为了好看，而是与使用方式紧密相连。说明中还提到，它可能用于部落结盟时共饮盟誓，不过这是一种推测，器物上没有文字可以直接证明。也有人把它和后世的交杯酒联系起来，这种联想很有吸引力，但目前缺少直接证据，说明中同样提醒还需要进一步考证。\n\n所以，这件双连壶真正能确定的，是它的工艺，以及它引出的一个问题：在五千多年前，人们是怎样借助一件器物，表达彼此之间的联系的？它给出了一条线索，却没有给出完整的答案，这也正是它值得你停下来仔细看的原因。下次再看到类似的器物，不妨也像这样，先看形状，再想用途。"}},{"museum_id":"henan","language":"zh","id":"henan-11","position":10,"title":"王子午鼎","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"春秋时期（公元前770—前476年）"},{"label":"类别","value":"青铜器·礼器（鼎）"},{"label":"材质","value":"青铜"}],"object_url":null,"image":{"src":"/images/paintings/henan-11.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:“王子午”青铜鼎（附匕）03671.jpg","license":"CC BY-SA 4.0","author":"Cangminzho"},"guide":{"short":"先看它的身形。这是一件鼎，三足托起饱满的腹部，古人用它盛放或烹煮肉食，用于祭祀。王子午鼎属于春秋时期的楚国，楚国是南方的大国，它的青铜器有着自己的面貌。这件鼎最值得留意的，是器内铸有长篇铭文，字数超过八十，这一点让它显得与众不同。据中国日报报道，它是一件很有代表性的楚式鼎，楚地工匠的风格在其中清晰可见。器身略有收束，三只蹄形足稳稳地立在地上，器表还附着六只兽形装饰，那是用失蜡法铸出的立体形象。它的高度大约在半米上下，抬头看去，像一口能盛放整套祭品的大锅。请你想象一下：热气从鼎口升起，人们围着祭台，香气弥漫。一件炊器能被铸上这么长的文字，本身就说明了它在礼仪中的分量。","expansion":"再说说它的出土地。1978年，考古人员在河南淅川县下寺发掘了一座春秋楚墓，这件鼎就出土于那里。这片土地如今位于丹江水库库区，也正是南水北调工程的一部分，现代工程的水面之下，埋着两千多年前的楚国历史。据部分资料，王子午被认为是楚庄王之子，还曾担任楚国的令尹，也就是执掌国政的高级官员。不过这一身份属于传统说法，学界仍有讨论，听的时候不妨把它当作一种可能。据信民文章介绍，水库下方原本淹没着丹阳城，丹阳正是楚国早期的都城，因此这一带的发掘备受关注。另外，有资料提到墓中原本有一组形制相同、大小不同的鼎，但数量的说法并不一致。所以，眼前这件究竟是孤品，还是一组中的一件，目前仍不能完全确定。","long":"想象一口锅，既能盛放祭祀用的肉食，又能把铭文留在自己的内壁上。王子午鼎就是这样一件器物。它是春秋时期楚国的青铜礼器，也是理解楚国礼器风格的一个好例子。\n\n先看造型。鼎是三足的器具，有腹有足，可以直接架在火上烹煮。这件鼎的腰身微微收束，腹部圆润饱满，三只蹄形足稳稳地托着器身，整体比例显得柔和。不妨在看它的时候，留意足与腹之间的过渡。这种形态承袭了商周以来鼎的传统。器身上另有六只兽形装饰，据河南博物院相关报道，它们是用失蜡法铸造后附着在器表上的，立体地凸出于器壁。器表的纹饰分为三组，花纹层次分明，在光线下会呈现出明暗的变化。\n\n这件鼎的分量，也体现在它的文字上。器内壁铸有铭文，各家资料统计的字数略有出入，但都超过八十字。这样的长度，在一件炊器上格外引人注目。文字的完整释读，仍需参考考古报告，这里不作展开，我们只需知道，这段文字与器物一同流传至今。\n\n器物的名字来自铭文中提到的王子午。传统上，人们认为他是楚庄王之子，还曾担任楚国的令尹。这种身份判断，建立在文献与铭文的对应之上，但学界仍有讨论，所以听的时候，不妨把它当作一种可能的解释。\n\n它的出土经历同样值得一听。1978年，人们在河南淅川县下寺的一座春秋楚墓中发现了它。今天，这片地方位于丹江水库库区，正是南水北调工程的一部分。一件两千五百多年前的青铜器，在现代工程的水位之下被重新发现，水库下方原本淹没着的丹阳城，正是楚国早期的都城，这样的地理背景值得一提。这种时间上的错位，让人对历史的深度多了几分感受。\n\n最后，不妨想象它在祭台上的情形。鼎中的肉汤翻滚，热气升腾，人们依礼而立，完成一场仪式。一件炊器能成为礼器，靠的不只是它的大小，更在于它所承载的身份与秩序。这一点，是读懂这口鼎的关键。"}},{"museum_id":"henan","language":"zh","id":"henan-12","position":11,"title":"王孙诰编钟","category":"乐器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"春秋时期（约公元前6世纪）"},{"label":"类别","value":"青铜乐器·编钟（甬钟组）"}],"object_url":"https://www.chnmus.net/ydgyt/collection/details.html?id=7100016422079696896","image":{"src":"/images/paintings/henan-12.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:Sun_Gao_Bianzhong,_picture4.jpg","license":"CC0","author":"Huangdan2060"},"guide":{"short":"您面前这二十六件青铜钟，每一件都是为敲击而铸，也为发声而生。考古学者称它们为甬钟，因为钟顶那根中空的柄叫“甬”。这套钟最特别的地方，在于每一件都能发出两个音高，取决于敲在哪里。正面的鼓部和侧面的鼓部同时敲响，会形成一组和谐的三度音程。整套钟的音域跨越约四个半八度，对于两千五百年前的乐器来说，这样的范围相当可观。据河南博物院介绍，它出土于淅川下寺楚墓，是目前中国已发现的春秋时期规模最大、数量最多的编钟。钟的造型固然讲究，但真正让它与众不同的，是每一件钟里藏着的两种声音。请您站在近处，细细听一听，您就能感受到，这些钟当初是为了什么而造的。这正是音乐与器物结合时最奇妙的地方。","expansion":"钟身上刻有一段113个字的铭文。据博物院的释读，作钟者名叫王孙诰，钟是为了娱乐楚王、诸侯的嘉宾、父兄和众士而作，并希望它万年无期地流传下去。这段文字把人带到宴飨与礼乐的场合中，也与钟的规模和音域相互呼应。不过，铭文本身仍有争议。近期一篇网络文章，作者只有一人，尚未经过同行评议，它提出铭文的文字可能抄自旧金山亚洲艺术博物馆收藏的一件钟，并认为这些文字是近代才加上去的。这篇文章并没有说这些钟是假的。它质疑的是铭文和作者的身份。所以您可以把“王孙诰”当作博物院的读法，而把这个问题当作仍然开放的讨论。如果您对这些争议感兴趣，不妨比较铭文的拓片与钟体本身，那才是判断的起点。","long":"先看数量。二十六件青铜钟排成一列，每一件都是甬钟，名字来自钟顶那根中空的柄。很多人停在器型上，但这套钟真正的故事藏在声音里。据河南博物院介绍，每件钟都经过设计，能同时发出两个音高：正面的鼓部和侧面的鼓部各对应一个音，两者同时敲响时，会形成一组和谐的三度音程。整套钟的音域跨越约四个半八度，放在公元前六世纪前后的乐器中，这是相当宽广的范围。博物院还称，它在已发现的春秋编钟中，规模、数量与音色都居首位。这些说法来自博物院自身，但它们建立在实物之上，值得您带着耳朵去验证。\n\n这套钟出土于河南淅川下寺的一座楚墓。楚是南方的大国，核心地区在长江中游一带，它的青铜器和音乐习俗，与北方诸侯的风格有明显差异。在周代礼制里，编钟的数量与组合常与主人的身份等级相连，钟的多少和音域的宽窄，本身就是一种地位的宣示。试着想象一下：在厅堂之中，钟声一层层荡开，宾客与贵族共同聆听，这才接近它原本的处境。\n\n钟上的铭文有113个字。据博物院释读，作钟者名叫王孙诰，钟是为了娱乐楚王、诸侯的嘉宾、父兄和众士而作，并希望它万年无期地流传下去。这些文字指向一个公开的礼乐世界，音乐要被许多人听见，而不是只留给一个人欣赏。\n\n不过，铭文本身仍有争议。近期一篇网络文章，作者只有一人，尚未经过同行评议，它提出铭文的文字可能抄自旧金山亚洲艺术博物馆收藏的一件钟，并认为这些文字是近代才加上去的。这篇文章并没有说这些钟是假的。另有文章对墓主的身份提出了不同看法，因此“王孙诰”这个名字，应当被看作博物院的一种读法，而不是定论。\n\n所以，请把这套钟当作一件可以演奏的乐器来看。作者的名字或许还有争论，但这些钟被设计出来要发出的声音，是清楚的。"}},{"museum_id":"henan","language":"zh","id":"henan-14","position":12,"title":"金缕玉衣","category":"玉器·金器·兵器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"西汉（约公元前206年—公元25年）"},{"label":"类别","value":"玉器·葬服"},{"label":"材质","value":"玉片，金丝"}],"object_url":null,"image":{"src":"/images/paintings/henan-14.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Jade_Suit_Sewn_with_Gold_Thread.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"请您仔细看这件金缕玉衣。它并非整块玉料雕成，而是由二千零八片形状、大小各异的玉片拼缀而成。玉片多呈青绿色，也夹杂着浅色和深色的。玉片之间以金丝连缀，把一件依人体制成的衣服串在一起。它分为头部、上衣、裤筒、手和鞋五大部分，每一处玉片的排布都照着身体的样子来安排。汉代的金缕玉衣，是帝王和高级贵族死后入殓所用的殓服，用来护持逝者的遗体，人们还相信它能助人羽化成仙。这件玉衣1985年出土于河南商丘永城僖山一号汉墓，属西汉时期。它让我们直观地看到，汉代高等级墓葬中用玉护身的做法究竟是什么样子。站近些，顺着一道金丝从一片玉走到另一片，就能看见古人怎样让坚硬的石头服帖地贴合人身。","expansion":"除了衣身，这套玉衣还配有几件小器物，看懂它们，就能明白玉衣在整套丧葬用品中的位置。据河南博物院的介绍，随葬的有供手握的玉猪、口中含的玉蝉，以及玉耳塞和玉鼻塞。口含玉蝉，常被解读为象征重生，不过这是学者的阐释，器物上并没有文字可以证明。玉猪的寓意也属于推测，这些解释都不宜当作确定的事实。耳塞和鼻塞体积不大，却与衣身一样，是整套随葬玉器中不可分割的一环。这些器物与衣身放在一起，说明玉衣并不只是穿在身上的衣服，而是一套为逝者准备的葬具中的一部分。至于下葬的是谁，目前仍不能确定。有报道把此墓与梁国王室联系起来，但具体是哪一位梁王，尚未得到确认。在没有铭文或可靠记录加以证实之前，墓主身份只能存疑。","long":"请先看颜色。您大概会以为玉衣是一件雕刻作品，走近才发现，它是由二千零八片玉片拼成的。这些玉片大小、形状都不相同，数量最多的是青绿色，也有浅色和深色的。它们覆盖了头部、上衣、裤筒、手和鞋这五大部分，合在一起，就成了一件与人体同形的衣服。玉片之间用金丝连缀，丝线把每一片都系在一起，使整件衣服保持它应有的形态。\n\n它的名字叫金缕玉衣，读作jīnlǚ yùyī，意思是用金线缀合的玉制殓服。这里的“金缕”二字值得一提。汉代也出现过用银线、丝线缀合的玉衣，学界常把所用线材与墓主身份联系起来。不过西汉初年的等级制度尚不十分严整，线材与身份之间的对应，只能作为大致的参考。就这件而言，金丝在当时是贵重的材料，是它最引人注目的特点之一。\n\n这件玉衣是一件殓服，也就是入殓时穿在逝者身上的衣物。据河南博物院的介绍，这类玉衣是汉代帝王和高级贵族死时使用的，它的作用是保护遗体。人们还相信，玉有助于逝者升仙，得到长生。这是当时人的信仰，属于对死后世界的想象，并不是可以被证实的结果。因此，我们应当把它看作人们的信念，而不是玉衣的实际效果。\n\n再看那些随葬的小器物。记录中提到，手中握着一只玉猪，口中含着一只玉蝉，耳中和鼻中各塞着玉塞。口含玉蝉，常被解读为象征重生，但这是学者的阐释，器物上并没有文字可以确证。玉猪的寓意同样只能作为推测。这几件器物与衣身一起，说明玉衣是整套葬具的一部分，而不只是一件衣服。\n\n这件玉衣1985年出土于河南商丘永城的僖山一号汉墓，时代为西汉。至于墓主是谁，目前没有定论。有报道把这座墓与梁国王室联系起来，但具体是哪位梁王，尚未得到确认。在没有可靠证据的情况下，墓主身份只能存疑。\n\n那么，它为什么值得今天的观众停下脚步？一方面，它让我们看到，一个高级贵族家庭能够调动怎样的财力与工匠之力，去为死后的世界做准备；另一方面，它也呈现出一个难题：如何让坚硬的玉石服帖地贴合人体的形状。走近些，顺着一道金丝，从一片玉走到另一片，您就能看到那套工艺是怎样把整件衣服连在一起的。"}},{"museum_id":"henan","language":"zh","id":"henan-15","position":13,"title":"三彩角形杯","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"唐代（618—907年）"},{"label":"类别","value":"陶器·明器（随葬品）"},{"label":"材质","value":"陶质，黄、绿、白三色釉"},{"label":"尺寸","value":"长14厘米；高7.0厘米；口径7.0厘米"}],"object_url":"https://www.chnmus.net/ch/collection/appraise/details.html?id=512155217003765138","image":{"src":"/images/paintings/henan-15.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20260520_Tri-Color_Glazed_Pottery_Cup_Shaped_of_Horn.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"先看杯子的顶端。这只角形杯弯出一道弧线，杯口是椭圆形的。靠近口沿的地方，一个动物的头回过来，朝向杯子的尾部，嘴里衔着一枝花。花枝搭在杯沿上，把动物的头和杯口连在一起，就成了拿杯子的把手。杯身满布卷草纹，黄、绿、白三种釉色覆盖全身，颜色鲜亮。这种造型并不是中国本土的。古希腊人称它为rhyton，中文音译作“来通”，原本是外来的器物。唐代工匠把这个外来的轮廓接过来，用自己的陶土和彩釉重新做了一遍。杯子长约十四厘米，正好能放进一只手掌。至于那个动物到底是什么，至今没有定论。河南博物院认为它更像一只绿孔雀，所以民间常叫它孔雀杯。陕西历史博物馆则认为是龙头。两种说法各有道理，你可以自己判断哪一种更让你信服。","expansion":"刚才说的是外形和那个回头的动物，现在来说说它为什么会被放进墓里。这件杯子出土于1976年，地点是郑州西郊的后王庄。博物院把它归为明器。明器是专门为随葬准备的器物，留给逝者在另一个世界使用，并不是拿来在餐桌上盛酒、盛水的日常用具。所以它虽然长得像一只杯子，身份却是陪葬品。博物院还特别指出，即使是随葬用的器物，工匠在外观上依然下了不少功夫。\n\n再说材料。唐三彩一般属于低温铅釉陶器，胎土多为白色，常常经过两次烧成。这件杯子也以黄、绿、白三色为主，它是陶器，不是瓷器。\n\n关于年代，名片上只写了唐代，博物院并没有给出一个直接的日期。更具体的判断，是把它和同一时期墓葬中的几件器物进行对比得出的，大致在唐高宗、唐中宗时期，也就是七世纪后期到八世纪初。换句话说，这是依靠对比做出的推断，不是杯子上刻着的年份。","long":"先别急着看颜色，先看它的形状。这只杯子弯成一支角的样子，杯口是椭圆形的，从敞口的一端往另一端，弧度越来越明显。杯身上的卷草纹绕来绕去，黄、绿、白三种釉色覆盖了全身，色彩鲜亮。它长约十四厘米，高约七厘米，正好能让人用一只手托住。\n\n最让人挪不开眼的，是杯口附近那个动物的头。它回过头来，朝向杯子的尾部，嘴里衔着一枝花。花枝搭在杯沿上，动物的头和杯口就这样连在一起，形成了一个把手。也就是说，这个把手不是单纯的装饰，它让整只杯子有了可以拿起来的理由。\n\n那么这个动物到底是谁？大多数人第一眼会想到孔雀。河南博物院认为，杯身上的卷草纹，加上颜色和头后翘起的部分，看起来更像一只优雅的绿孔雀，所以民间也叫它孔雀杯。但陕西历史博物馆认为它应该是龙头。两种说法各有道理，博物院自己也没有下定论。这提醒我们，唐代器物上的动物形象，不一定只有一种固定的含义。在这里，它更像一道待你判断的谜题。\n\n它的造型来路很远。古希腊人把这种角形的饮器叫作rhyton，中文音译为“来通”。它是一种典型的外来器物，经由丝绸之路等交往渠道传入中国。而中国早在唐代以前，就已经有用动物角制成的角形杯，所以这类造型并不完全陌生。唐代工匠把外来的轮廓接过来，用中国的陶土和彩釉重新做了一遍。远看像外国的样子，细看却是中国的手艺。\n\n接下来说它的用途。这件杯子是1976年在郑州西郊后王庄出土的，博物院把它归为明器，也就是专门随葬、供逝者使用的器物。它的外形像一只杯子，但它并不是为了餐桌上的日常使用而做的，被放进墓里，是为了陪伴逝者。博物院还提到，工匠在制作这类随葬器物时，依然很讲究外观。\n\n至于年代，名片上只写了唐代。更具体的判断，是博物院把它和同时期墓葬中的几件器物相比较后推断出来的，大约在唐高宗、唐中宗时期，也就是七世纪后期到八世纪初。这是一种推断，而不是杯子上直接刻着的日期，听的时候，把它当作合理的估计就好。\n\n那么，它为什么值得今天的我们多看几眼？一个不大的杯子里，既有外来造型的影子，也有唐代工匠的自信。卷草纹和那个回头的动物，正是一件中国作品回应外来想法的方式。"}},{"museum_id":"henan","language":"zh","id":"henan-16","position":14,"title":"绿釉陶立狗","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"汉代（公元前206—公元220年）"},{"label":"类别","value":"陶器·明器"},{"label":"材质","value":"陶胎，绿釉"}],"object_url":null,"image":{"src":"/images/paintings/henan-16.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20210220_Green_glazed_pottery_standing_dog,_Henan_Museum.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"先看姿态。这只狗四足着地，身子挺立，通身覆着一层光润的绿釉。陶土本是朴素粗糙的材料，经釉色一罩，表面便泛出玻璃般的光泽。片名“绿釉陶立狗”已经把要点交代清楚：陶质、绿釉、立姿。\n\n它却不是用来遛的宠物，而是一件明器。古人称专为随葬而作的器物为明器，有“神明之器”的意思，与活人日常使用的器物相对。汉代人家在墓中放入动物、器物和日常生活的模型，好让逝者到了另一个世界，仍有所依傍。狗是家中最常见的伙伴之一，一般认为，它进入墓葬后的任务很简单：陪伴主人走完下一段路。\n\n这类小型陶塑在汉墓中并不少见，多半成批制作，形态朴素。釉色承担了大部分装饰效果。同样的陶土，换上一层绿釉，便从寻常的日用粗器，变成了值得细看的小物件。","expansion":"为什么要为随葬之物施釉？汉代的随葬风气，已不再只属于皇帝与贵族。随着做官的人越来越多，有些普通家庭也有能力为墓室布置一整套生活的模型。陶土取得容易，又好成形，从粗陶到施釉器，都可以用它来做。\n\n绿釉的做法也值得一说。汉代绿釉多为铅釉，即在釉料中加入含铅的助熔剂，再配合铜等呈色元素，涂在器表后入窑烧成一层玻璃质的薄膜。在汉代陶器中，上釉往往多一道工序，也更费工。上了釉的器物比素陶更亮，釉层的厚薄与流动，也让颜色有了深浅变化。\n\n不过要说明的是，这件藏品的官方记录尚未核实。它究竟是不是铅釉，出土于何处，属西汉还是东汉，目前都还不能断定。聆听时，请把这些当作待确认的信息，而不要当作定论。","long":"许多参观者第一眼会把这样的小狗当作玩具，或是装饰摆件。仔细看，它的片名“绿釉陶立狗”已经道出了大半：一只站立的狗，用陶土塑成，外面覆着一层绿釉。这几个字背后，是汉代人对死亡的一整套想法。\n\n这件小狗是明器。古人把专为随葬而做的器物称为明器，有“神明之器”的意思，与活人日常使用的器物相对。汉代墓葬里，常放着逝者生前熟悉之物的替身：农舍、牲畜、灶具、仆从，还有各种动物。它们的意思很朴素，就是让逝者到了另一个世界，仍有生活所需。狗是汉代家庭中最常见的动物之一，自然也进入了这组随葬的队伍。按通行的理解，它的任务是陪伴主人走完那段路。\n\n用陶土做这类器物，成本不高。陶土随处可得，又容易成形，许多家庭都能为亲人备下一些模型。而让这件小狗显得不同的，是釉。汉代的绿釉多为铅釉，釉料涂在器表，经窑火烧成一层玻璃质的薄膜，把朴素的陶胎裹上一层明亮的光泽。同样是陶土，施了釉，便显得更加体面。陶俑、陶畜之类的随葬品，常常是模制部件与手工修整相结合，同一批之中，也未必件件完全相同。\n\n那么，是谁会为亲人准备这样的随葬品？汉代的权力和财富，已不再只集中在皇帝与贵族手中。随着做官的人越来越多，一些家庭也有了能力把墓室布置得更完整。随葬品于是成了身份与生活条件的一种表达。一只绿釉小狗，既寄托着对伙伴的思念，也透露出主人家的光景。\n\n需要坦率地说明的是，这件藏品的官方记录尚未核实，因此它确切的年代、出土地点，以及釉料是否为铅釉，目前都还不能断定。我们能确定的，是它属于汉代墓葬中用陶塑日常动物与器物、为逝者延续生活的传统。\n\n这大概是这件器物最动人的地方。一个在人间陪伴过主人的动物，被人用陶土和釉色再塑一次，送入地下，继续陪伴。这也是为什么，一件看似简单的陶狗，值得我们停下来多看一会儿。"}},{"museum_id":"henan","language":"zh","id":"henan-17","position":15,"title":"四神画像陶灶","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"汉代"},{"label":"类别","value":"陶器·明器"},{"label":"材质","value":"陶"}],"object_url":null,"image":null,"guide":{"short":"请您仔细看这件小小的陶灶。它不是用来做饭的，而是一件明器（míng qì），即专为随葬而制作的器物。汉代人普遍相信，人死后仍需生活，于是把与日常相关的器物做成模型放进墓中，让亡者在另一个世界也有所供养。这件陶灶就是这样的“厨房”。它看上去只是一件小陶器，却保存着汉代人对死后生活的想象。它的主题是四神，即青龙、白虎、朱雀、玄武，原本分守东、西、南、北四方，护卫天空与方位。四神在汉代墓葬与器物中十分常见，但每件作品的画法和位置都不尽相同。把守护者的形象放在灶上，就像把一套秩序带进了厨房。它是一件厨房的替身，让亡者在墓中仍有饮食的依靠。请您想一想，这些守护者要护卫的，究竟是灶前的人，还是墓中的生活？","expansion":"这件陶灶的另一层价值，在于它与真实厨房的关系。汉墓中出土的陶灶，多是照着当时居室里的灶做的，灶门、灶面与烟孔都有生活原型可循。这说明明器并非随意捏造，而是力求逼真，好让死者在另一个世界继续照顾日常所需。汉人还敬奉灶神，灶神与饮食、家居相连。这件陶灶上的四神，或许也与这类信仰有关，但它是否专为灶神而作，目前无法证实。另外要提醒的是，四神在汉代器物上的排布并不总是统一，不同墓葬、不同材质中，同一形象承担的角色也可能不同。所以面对这件陶灶，我们能确定的是它的功能与主题，至于每一处纹样的具体寓意，仍有讨论的空间。您不妨注意灶面与灶壁上的纹饰，想想它们在厨房的日常里处于怎样的位置。","long":"请先看这类陶灶的样式。灶门、灶面上承放釜的火口，还有旁边的烟孔，都在模仿汉代人家里真实的灶。可是它并不是用来做饭的。汉墓中常见一类器物，叫明器（míng qì），是专为随葬而制作的东西。人们相信，死者在另一个世界仍需要吃喝、居住和劳作，于是把灶、仓、井、猪圈这类日常用品做成模型，放进墓里，供亡者使用。陶灶正属于这一类。陶制明器在汉墓中相当常见，许多阶层的墓葬中都能找到，说明这种随葬观念相当普及。\n\n而且，明器往往不是单独出现的。一件灶，配上仓、井与其他器物，墓中便形成一个微型的家。换句话说，墓主人需要的不只是一块灶，而是一整套能够运转的日常生活。陶土烧成的器物，形体小、制作相对简便，正适合这种成组随葬的需要。这一点，或许比单件器物的精致程度更能说明它的用途。\n\n灶上的装饰，则把我们的视线引向另一个世界。这件陶灶以四神为主题。四神就是青龙、白虎、朱雀、玄武，汉代人常用它们来标示东、西、南、北四方，也被看作守护方位的神灵。玄武是龟与蛇的组合，朱雀位于南方，白虎居西，青龙居东，这是一套比较完整的方位安排。可是，四神在汉代器物上的排布并不总是统一，不同墓葬、不同材质中，同一形象的位置与角色也会有所变化，所以不能把某一种排法当作固定答案。这种一边是最日常的灶、一边是最遥远的天地的组合，正是理解这件器物的入口。\n\n同样需要说明的是，这些图像在灶上具体起什么作用，目前并无定论。汉人敬奉灶神，这一信仰或许与灶的神圣性有关，但这件陶灶是否专为灶神而作，尚无法证实。因此，比较稳妥的看法是：这是一件模仿日常厨房的随葬陶器，装饰着四神，它的首要意义，是为死者准备一个仍能生活的空间。请您再看一眼灶面与灶壁，想象一下，在这样一座小灶前，汉代的一家人曾经如何生火、如何做饭。"}},{"museum_id":"henan","language":"zh","id":"henan-18","position":16,"title":"父乙角","category":"青铜器","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"西周早期"},{"label":"类别","value":"青铜酒器·角"},{"label":"材质","value":"青铜"},{"label":"尺寸","value":"通高29厘米；口长20.3厘米，口宽9.8厘米"}],"object_url":"https://www.chnmus.net/content/redirect?id=512155913655553326","image":null,"guide":{"short":"请先看器盖。这件青铜酒器的盖子像一道屋脊，顶上有一个半环形的小钮。器身一侧，一个半环形的鋬，末端做成兽首。再看它的颜色。这个年代的青铜器大多因为埋在地下几千年而锈成青绿色，这一件却近乎乌黑，表面发亮，很像一层老漆。它叫角，是一种酒器。器口微微张开，腹壁较直，底下三只三棱锥状的足撑着器身。器盖内和器身上各有一段十二字的铭文，内容相互对应，其中有“父乙”两字，是对一位已故父亲的称呼。“宝尊彝”一语，常见于西周礼器，大意是珍贵的礼器。它属于西周早期，约三千年前。所以看这件器物，不妨先看颜色，再读铭文，最后看那只后配的足。黑亮的表面、十二个字和一只后配的脚，三样东西放在一起，就能看出它的来历与经历。","expansion":"这件器物的故事，要从一场水坝工程说起。一九八六年八月，当地农民在浉河滩修筑水坝，在河道的黑色淤泥中发现了一批青铜器，共收集到十四件。它们是从河床淤泥里整批找到的，资料没有说明它们原先放在何处，也没有解释为何沉入河中，我们不做推断。其中有两件形制相近的父乙角，河南博物院收藏的是其中一件。两件器物为何会出现在同一地点，同样没有定论。它们很可能曾是一组器物，但这只是一种可能，不是已经确认的结论。再看鋬下的那只足。它在出土时已经残失，现在看到的是后来配上的。也就是说，这件角在三千年的岁月里，经历过一次修补。把这些经历放在一起看，它既是一件西周早期的酒器，也是一件被偶然发现、又被认真保存下来的文物。","long":"站在这件青铜器前，先看它的颜色。这个年代的青铜器，大多在地下埋了几千年，表面锈成青绿色，或者斑斑驳驳。这一件却近乎乌黑，表面发亮，记录中把它比作黑漆古。它是一件角，属于酒器。器口微微张开，口部呈长条形，长约二十厘米，宽不到十厘米。器身中间略向内收，两翼向上翘起，腹壁比较直，底部圆润，下面由三只三棱锥状的足撑着。其中一侧的足上方附着一个半环形的鋬，末端做成兽首。盖子像屋脊一样隆起，顶上有一个半环形的小钮。通高约二十九厘米。记录还说它兼有温酒的功能，不过具体怎样使用，资料没有更多说明，我们也就不做猜测。器身布满纹饰。兽面纹、三角纹和龙纹，都以细密的云雷纹作为底纹。器表还有竖向凸起的棱线，名叫扉棱，它们把纹饰分成了几组。记录把这种纹饰工艺称为“三层花”，但这个说法的确切含义，目前还没有统一的解释，所以这里只能说它的纹饰很密、很精细。最值得细看的，是器盖内和器身上的铭文。两处各有十二个字，内容对应，相当于同一段文字刻在了器物的两个部分。其中的“父乙”两字，是对一位已故父亲的称呼。“乙”是十天干之一，这类名号多用在礼器上。铭文里还有“宝尊彝”一语，常见于西周礼器，大意是珍贵的礼器。由此看，它与祭祀祖先的活动有关，这一点比较有把握。它也有自己的经历。一九八六年八月，当地农民在浉河滩修筑水坝，在河道的黑色淤泥中发现了一批青铜器，共收集到十四件。其中有两件形制相近的父乙角，河南博物院收藏的是其中一件。两件器物为什么会在同一地点出现，资料没有给出结论。再看鋬下的那只足。它在出土时已经残失，现在的是后来配上的。这个细节提醒我们，这件器物并不是一直以原样保存到今天的。所以，读它的铭文、看它的纹饰时，也别忽略它的脚。它的器形、纹饰和文字，来自三千年前的工匠与主人；它的表面，是我们今天看到的样子；它的修补痕迹，则属于后来的故事。三者叠在一起，才构成这件角完整的面貌。"}},{"museum_id":"henan","language":"zh","id":"henan-19","position":17,"title":"三彩狮形座枕","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"宋代"},{"label":"类别","value":"瓷器"}],"object_url":"https://www.chnmus.net/content/redirect?id=7066681088168431616","image":{"src":"/images/paintings/henan-19.jpg","sourceUrl":"https://commons.wikimedia.org/wiki/File:20230217_Three-color_Porcelain_Pillow_in_Lion_Shape.jpg","license":"CC BY-SA 4.0","author":"Windmemories"},"guide":{"short":"先别急着看狮子，先看名字。它叫三彩狮形座枕，「枕」字说得明白，这件东西首先是用来枕头的。狮子的身体，就是托住人头的那一部分，它要的是稳，是让人一夜睡得踏实。河南博物院把它定为宋代，大约是公元960年到1279年之间的这一段时间。接下来说那个「三彩」。字面上是三种颜色，可这只是一个沿用已久的叫法，颜色未必正好三种，数字不必当真。所以不妨走近一点，顺着狮子的轮廓去看它的釉色，看颜色怎样过渡、怎样聚在一处。还有一处容易被忽略：名字里的「座」字，提醒你这件枕不是孤零零一件，它有承托的部分，那才是让它稳住的关键。这些地方，比数字更能告诉你它是怎样做成的。站在它面前慢慢看，你会发现，一件小小的枕，也能有很多值得停下来的细节。","expansion":"「三彩」这个名字，还值得再多想一层。唐三彩大家比较熟，宋代的同类器物常被叫作宋三彩，可这个叫法是否准确，学界并没有完全统一的看法。有研究者认为，这类器物大体属于多色的低温铅釉器。铅釉在烧制时比较容易流动，所以釉色之间往往相互渗开，形成过渡，而不是一道一道截然分开的色块。博物院把这件器物归入瓷器，可瓷与陶的分别，要看胎体才能判断，眼前的釉面却无法替代这一步。因此，站在它面前，不妨先把名字放在一边，只看釉层的光泽和流淌的痕迹。那一层釉，就是做工留下的线索。如果你此前见过其他宋代的瓷器，不妨在脑子里把两者放在一起比一比，差异往往就藏在釉色和胎体的交接处，而这正是普通参观者最容易忽略、却最能体现工艺差别的地方。","long":"你先想象一件事：有人在夜里枕着一只狮子睡觉。这件东西叫三彩狮形座枕，名字里的「枕」字说得直白，它首先是一件用来枕头的器物。狮子的形体，承担的是托住头的任务，它的高度、它的重心，都得为一个人的睡眠服务。\n\n名字里的「座」字，大致指底座或承托的部分。河南博物院把它定为宋代，也就是公元960年到1279年之间。它在博物院的分类里归入瓷器。不过这里有一点需要留意。我们手头的官方记录比较简略，只给出名称、年代和类别，没有标注尺寸，没有材质描述，也没有出土地点和制作者。所以它究竟用的是什么胎、烧到什么温度，这里不能替它下结论。\n\n再说那个「三」字。三彩字面是三种颜色，但宋代的这类器物常被沿用这个叫法，它的颜色未必正好是三种。有研究者认为，这类名称不够严谨，它们大体是多色的低温铅釉器。铅釉在烧制时比较容易流动，釉色之间常常相互渗开，形成过渡，这与瓷器的高温釉做法并不相同。学界在这一点上仍有讨论，所以最稳妥的办法，是让你自己的眼睛去看釉色的层次，再与标签对照。\n\n狮子在这件器物上的意义，我们也不能随意说。狮子的形象在中国艺术里出现得很多，在佛教语境、宫廷语境和日常器物上，它的含义并不一样。没有可靠的材料证明这件东西原本在什么场合使用，所以更稳妥的理解，是最朴素的那一种：它是床上的物件，是为了让人枕得舒服。\n\n这个朴素的理解，恰恰很有味道。狮子的威猛，被转化成了一个安静、家常的用途。它不需要传说，也不需要仪式，只需要一张床和一个人的头。站在它前面，你可以试着想象它被放在枕席边，承受的是一夜的重量。装饰与实用，在这里并不分开。看它的时候，不妨先把它当作一件工具，再去欣赏它作为雕塑的部分，你会发现许多细节，正是从这个用途里来的。"}},{"museum_id":"henan","language":"zh","id":"henan-20","position":18,"title":"白釉莲瓣碗","category":"陶瓷","subtitle":null,"artist":null,"facts":[{"label":"时期","value":"辽代（916—1125年）"},{"label":"类别","value":"瓷器"},{"label":"材质","value":"白釉瓷"}],"object_url":"https://www.chnmus.net/content/redirect?id=7066680004351889408","image":null,"guide":{"short":"请您先看看碗壁。碗身上一瓣一瓣向外鼓起的纹样连成一圈，像一朵半开的莲花，这就是莲瓣纹。它是一件日常使用的器物，白色的釉面素雅干净。釉色单一，没有其他色彩分散注意力，于是器物的形状本身就成了主角，这也是白瓷最迷人的地方之一。这件器物属于辽代。辽是契丹人在北方建立的王朝，契丹人原本生活在草原，建国后却要治理人数众多的汉人和其他人群，这种多元的社会背景，是理解辽地器物的一条线索。莲花在中国流传已久，与佛教的关系尤其密切，但放在一只日常的碗上，它首先可能只是为了好看。您可以绕着碗走一圈，看莲瓣在光线里明暗交替，一瓣接着一瓣地重复，让这只朴素的碗有了一种安静的节奏。不必急着走开，多停留片刻，它会慢慢显出自己的样子。","expansion":"这只碗现藏河南博物院，而辽的统治中心远在北方，两地相隔甚远，于是一个问题自然浮现：它究竟是哪里烧制的？目前没有定论。定窑在河北，北宋时是北方最具代表性的白瓷窑场之一，一直延续到金代。不少研究者因此把辽地的白瓷与定窑联系起来，认为器形和工艺沿着北方的窑场网络传播。但这种联系主要是推测，学界仍有争议。北方还有其他窑场烧制与定窑相近的白瓷，它们在釉色、胎体厚薄和表面处理上有细微差别，肉眼并不容易分辨。所以，这只碗可能来自辽境内的作坊，也可能出自定窑系统的窑场，甚至出自两者之间。判断需要依靠胎釉成分、器形和出土背景，而这些资料在目前公开的记录中还不完整。这个暂时没有答案的问题，恰好提醒我们，一件器物的身世往往要靠成分、器形和出土背景一点点拼起来。","long":"先从碗壁说起。绕着这只碗看一圈，会发现一连串莲瓣状的纹样，每一瓣都向外鼓起，连在一起，整只碗就像一朵半开的花。它的外形朴素，从类别上看是一件日常用器。莲花在中国艺术里有很长的历史，佛教寺院中常见莲花的身影，到这只碗烧制的时代，莲瓣已经是瓷器上相当熟悉的纹样。不过，纹样的意义并不是一成不变的。佛教把莲花看作纯净的象征，说它生于淤泥而不染，也与往生净土的想象相连。可是放在一只日常用的碗上，莲瓣很可能首先是为了好看，也可能对使用的人还带着一层佛教的联想。这两种理解都有可能，单凭一件器物，无法断定哪一种更接近当时的情形。\n\n白釉是另一处值得细看的地方。在辽代的北方，白瓷是一个重要的生产门类。辽朝由契丹人建立，契丹人原本生活在草原，立国之后统治着人数众多的汉人农民、工匠和官员，国家的器物生产因此借用了中原既有的技术与审美。一般认为，辽朝立国于十世纪初，到1125年为金所灭。在这一百多年里，北方的制瓷工匠不断摸索，白瓷的烧制逐渐成熟。\n\n这就引出一个关于这只碗本身的问题。它如今收藏在河南，离辽的核心统治区很远，那它究竟是在哪里烧出来的？有学者认为，辽地的白瓷与河北的定窑有关，定窑在北宋时是北方最具代表性的白瓷窑场之一。但北方还有其他窑场，烧出的白瓷在釉色、胎体厚薄和表面处理上只有细微的差别。目前的资料还不足以把这只碗准确地归入某一座窑。它可能出自辽境内的作坊，也可能来自定窑系统的窑场，甚至是两者之间的某个地方。这个暂时没有答案的问题，恰好提醒我们，一件器物的身世往往要靠成分、器形和出土背景一点点拼起来。\n\n回到眼前这只碗。从它的类别看，它是一件用于日常的器物，而不是为宫廷陈列准备的精品。它的纹样借用了佛教的莲花，它的白釉连接着北方的制瓷传统，它的来历则牵动着一个更大的问题：北方的技艺是怎样在不同人群和不同地区之间流动的。慢慢看它，您会发现，一件朴素的日常器皿，也能让人看到一段复杂的历史。"}}]$seed$::jsonb)
on conflict (museum_id, language, id) do update set
  position = excluded.position, title = excluded.title, category = excluded.category,
  subtitle = excluded.subtitle, artist = excluded.artist, facts = excluded.facts,
  object_url = excluded.object_url, image = excluded.image, guide = excluded.guide;
